register

* 被 [uvm_component_registry:get](https://github.com/jiru1997/VLSI-Design-verification-interview/blob/main/VLSI%20Design%20Verification/Functional%20Verification/UVM1.2%20source%20code%20analysis/03%3A%20uvm_base/chapter%2005%3A%20%20uvm_component_registry.md) 和 [uvm_object_registry:get](https://github.com/jiru1997/VLSI-Design-verification-interview/blob/main/VLSI%20Design%20Verification/Functional%20Verification/UVM1.2%20source%20code%20analysis/03%3A%20uvm_base/chapter%2002%3A%20uvm_object_registry.md) 调用，get 函数在静态变量 me 初始化的时候被挑用，因此最终 register 被调用的时机是: the first time any static member or method of this specialized class is accessed

```systemverilog
protected uvm_object_wrapper   m_type_names[string];
```
* 使用关联数组来保存被注册的代理对象 -> key:类名 value:代理对象

```systemverilog
protected bit                  m_types[uvm_object_wrapper];
```
* 使用关联数组来判断将要被注册的对象之前是否已经被注册过 -> key:代理对象 value:bit
* 如果当前被注册的类使用的是参数宏来进行注册，那么类名默认为unknown，所以不能被`m_type_names`注册而是被`m_types`注册，**如果参数化类使用普通方式注册，如果这个类被多次实例化，每一次会使用相同的名字进行注册，会导致警告**
* 当检查一个类是否被注册时候使用`m_types`，因为所有的类都会在这里注册，但是只有有名字的类才会在`m_type_names`注册

  <img width="940" alt="image" src="https://github.com/jiru1997/VLSI-Design-verification-interview/assets/66343787/d2f3f2d6-18d0-409c-a68e-0ca0f090ddc8">

* 查找针对于当前名字(代理对象的名字: 注册时候使用的 class 的名字的字符串形式，如果是带参数的 class 那么名字是 <unknown>)的 override 信息，并将信息进行转存，之后在查找 override 信息的时候就直接从转存的数组中查找

  * `m_inst_override_name_queues` 中存储的是在当前 component 注册之前已经执行的 override 信息，所以当前 component 开始注册的时候，需要将那一部分的信息转存到 m_inst_override_queues 中，m_inst_override_queues 存储的是已经注册了的 component 的 override 信息

  * `m_wildcard_inst_overrides`, 中存储的是使用 name override 并且路径中存在通配符的信息，所以每一个新的 component 在注册的时候都要检查一下名字和通配符是否 match，如果 match 同样将这条信息存储到 m_inst_override_queues 中

* 通常情况下这个函数就是在代理 class 调用 create 方法之前被调用，因此在真正创建 object 之前，需要将所有的相关 override 信息存放到 m_inst_override_queues 中，这样可以保证创建的时候可以使用到所有的全 override 信息，例如在 find_override_by_type 中，就没有对 wildcard 进行检查，因此如果不在这里提前进行检查并进行转存，那么之后将无法使用到 wildcard 的 override 信息。通常情况下 override 信息在 parent class 的 build phase 中被设置，而对 class 的实例化其后或者在 child class 中进行，因此这里需要进行转存.

  ```systemverilog
  // Test environment
  class my_env extends uvm_env;
    `uvm_component_utils(my_env)

    BaseDriver drv1, drv2, drv3;

    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction

    function void build_phase(uvm_phase phase);
      super.build_phase(phase);

      // Create drivers
      drv1 = BaseDriver::type_id::create("drv1", this);
      drv2 = BaseDriver::type_id::create("drv2", this);
      drv3 = BaseDriver::type_id::create("drv3", this);
    endfunction
  endclass

  // Test class
  class my_test extends uvm_test;
    `uvm_component_utils(my_test)

    my_env env;

    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction

    function void build_phase(uvm_phase phase);
      super.build_phase(phase);

      // Set wildcard override
      factory.set_inst_override_by_name("BaseDriver", "CustomDriver", "*.drv*");

      // Create environment
      env = my_env::type_id::create("env", this);
    endfunction

    function void end_of_elaboration_phase(uvm_phase phase);
      super.end_of_elaboration_phase(phase);
      // Print the test topology
      uvm_top.print_topology();
    endfunction
  endclass
  ```


* **注册时候使用的名字都是 class 的名字的字符串形式，并没有和 parent 路径拼接，这就是 name 和 path 的区别，name 用来找类型，path 用来找实例**

```systemverilog
function void uvm_default_factory::register (uvm_object_wrapper obj);

  // Check if the input object is null
  if (obj == null) begin
    uvm_report_fatal ("NULLWR", "Attempting to register a null object with the factory", UVM_NONE);
  end

  // Register the class into factory if it is not a parameterized class
  if (obj.get_type_name() != "" && obj.get_type_name() != "<unknown>") begin
    // Check if the type name already exists in m_type_names
    if (m_type_names.exists(obj.get_type_name()))
      uvm_report_warning("TPRGED", {"Type name '",obj.get_type_name(),
        "' already registered with factory. No string-based lookup ",
        "support for multiple types with the same type name."}, UVM_NONE);
    else
      // Add the object to m_type_names with its type name as the key
      m_type_names[obj.get_type_name()] = obj;
  end

  // Check if the object already exists in m_types
  if (m_types.exists(obj)) begin
    if (obj.get_type_name() != "" && obj.get_type_name() != "<unknown>")
      uvm_report_warning("TPRGED", {"Object type '",obj.get_type_name(),
                         "' already registered with factory. "}, UVM_NONE);
  end
  else begin
    // Add the object to m_types
    m_types[obj] = 1;

    // ========================================================================= //
    // Named Overrides:                                                          //
    // ========================================================================= //
    // It checks if there are any pre-existing named overrides for this object   //
    // type. If found, it creates a new queue for this object type in            //
    // m_inst_override_queues. It then copies the existing named overrides to    //
    // this new type-based queue. Finally, it removes the named override entry   //
    // from m_inst_override_name_queues.                                         //
    // ========================================================================= //
    if(m_inst_override_name_queues.exists(obj.get_type_name())) begin
       m_inst_override_queues[obj] = new;
       m_inst_override_queues[obj].queue = m_inst_override_name_queues[obj.get_type_name()].queue;
       m_inst_override_name_queues.delete(obj.get_type_name());
    end

    // ========================================================================= //
    // Wildcard Instance Overrides:                                              //
    // ===========================================================

set_type_override_by_type

* 被[component:set_type_override_by_type](https://github.com/jiru1997/VLSI-Design-verification-interview/blob/main/VLSI%20Design%20Verification/Functional%20Verification/UVM1.2%20source%20code%20analysis/03%3A%20uvm_base/chapter%2006%3A%20uvm_component.md)调用
* 如果想要实现override，必须保证original_type和override_type之间存在继承关系，在调用[uvm_object_registry:create](https://github.com/jiru1997/VLSI-Design-verification-interview/blob/main/VLSI%20Design%20Verification/Functional%20Verification/UVM1.2%20source%20code%20analysis/03%3A%20uvm_base/chapter%2002%3A%20uvm_object_registry.md)的时候，会通过cast来检查这种继承关系，如果是参数化的类，必须保证参数相同。在不使用参数的时候默认使用默认参数，只有参数相同的时候才有继承关系。


* 先检查传入的两个类型是否相同，如果相同直接退出。传入的参数都是代理类型，并不是实际类型
* 再检查传入的两个类型是否都已经注册，如果没有那么进行注册(因此理论上说就算之前这两个类型都没有在factory中注册过，也可以直接调用这个函数来进行重载，因为该函数内部会对传入类型进行补注册)
* 遍历所有已经override的类，查找当前类是否已经被重写。如果找到，则对原有信息进行更新，如果没有则插入一条新的override的记录
* 判断的依据是：
  * orig_type 相同(代理对象实例)
  * orig_type_name 相同(类名)

* 传入的路径信息为*，表示整个 UVM 树中所有的结点都会执行 override 操作。

```systemverilog
protected uvm_factory_override m_type_overrides[$];
```
* 这个队列中存储的是 [uvm_factory_override](https://github.com/jiru1997/VLSI-Design-verification-interview/blob/main/VLSI%20Design%20Verification/Functional%20Verification/UVM1.2%20source%20code%20analysis/03:%20uvm_base/chapter%2004:%20uvm_factory_override.md) 类型的变量


```systemverilog
function void uvm_default_factory::set_type_override_by_type (uvm_object_wrapper original_type,
                                                      uvm_object_wrapper override_type,
                                                      bit replace=1);
  bit replaced;

  // Check if original and override types are the same
  if (original_type == override_type) begin
    // Warn if types are identical, using type name if available
    if (original_type.get_type_name() == "" || original_type.get_type_name() == "<unknown>")
      uvm_report_warning("TYPDUP", {"Original and override type ",
                                    "arguments are identical"}, UVM_NONE);
    else
      uvm_report_warning("TYPDUP", {"Original and override type ",
                                    "arguments are identical: ",
                                    original_type.get_type_name()}, UVM_NONE);
  end

  // Register types if not already registered
  if (!m_types.exists(original_type))
    register(original_type); 

  if (!m_types.exists(override_type))
    register(override_type); 

  // Check for existing type override
  foreach (m_type_overrides[index]) begin
    // If original type matches (by object or name)
    if (
        // Check if the original type matches directly (by object reference)
        m_type_overrides[index].orig_type == original_type 
        ||
        (
            // Ensure the original type name is valid (not unknown or empty)
            m_type_overrides[index].orig_type_name != "<unknown>" &&
            m_type_overrides[index].orig_type_name != "" &&

            // Compare the original type name with the name of the input type
            m_type_overrides[index].orig_type_name == original_type.get_type_name()
        )
    ) begin
      string msg;
      msg = {"Original object type '",original_type.get_type_name(),
             "' already registered to produce '",
             m_type_overrides[index].ovrd_type_name,"'"};

      // If not replacing, inform and return
      if (!replace) begin
        msg = {msg, ".  Set 'replace' argument to replace the existing entry."};
        uvm_report_info("TPREGD", msg, UVM_MEDIUM);
        return;
      }

      // If replacing, update message and override info
      msg = {msg, ".  Replacing with override to produce type '",
                  override_type.get_type_name(),"'."};
      uvm_report_info("TPREGR", msg, UVM_MEDIUM);
      replaced = 1;
      m_type_overrides[index].orig_type = original_type; 
      m_type_overrides[index].orig_type_name = original_type.get_type_name(); 
      m_type_overrides[index].ovrd_type = override_type; 
      m_type_overrides[index].ovrd_type_name = override_type.get_type_name(); 
    end
  end

  // If no existing override was replaced, create a new entry
  if (!replaced) begin
    uvm_factory_override override;
    override = new(.orig_type(original_type),
                   .orig_type_name(original_type.get_type_name()),
                   .full_inst_path("*"),
                   .ovrd_type(override_type));

    m_type_overrides.push_back(override);
  end

endfunction
```


