* 保存名字中既不包括通配符也不和之前类注册时候使用的名字一直的名字的override信息 -> key:对象实例名 value:override 信息队列
```systemverilog
protected uvm_factory_override    m_wildcard_inst_overrides[$];
```
* 保存名字中含有通配符的名字的override信息，这里对信息不进行分类，全部存储到一个队列中
* 使用当前的名字查找，如果已经注册，则获取代理对象，通过代理对象调用`check_inst_override_exists`判断是否是重复操作，如果是重复则直接返回，如果不是重复则添加一条信息。
* 如果名字中包含通配符，那么一定无法在注册信息中找到对应的代理对象，则先遍历所有已经注册的类的名字，如果匹配，那么使用遍历得到的名字递归调用当前函数进行注册。
* 如果名字中不包含通配符，也不是之前类进行注册使用过的名字，那么将当前信息保存到`m_inst_override_name_queues`

  ![image](https://github.com/jiru1997/VLSI-Design-verification-interview/assets/66343787/c31276b8-2347-4997-b297-a14659bd4362)


```systemverilog
function void uvm_default_factory::set_inst_override_by_name (string original_type_name,
                                                      string override_type_name,
                                                      string full_inst_path);

  uvm_factory_override override;
  uvm_object_wrapper original_type;
  uvm_object_wrapper override_type;

  // 这里可能因为包含通配符所以获取不到
  if(m_type_names.exists(original_type_name))
    original_type = m_type_names[original_type_name];

  if(m_type_names.exists(override_type_name))
    override_type = m_type_names[override_type_name];

  // Ensure the override type is registered with the factory
  if (override_type == null) begin
    uvm_report_error("TYPNTF", {"Cannot register instance override with type name '",
    original_type_name,"' and instance path '",full_inst_path,"' because the type it's supposed ",
    "to produce, '",override_type_name,"', is not registered with the factory."}, UVM_NONE);
    return;
  end

  if (original_type == null)
      m_lookup_strs[original_type_name] = 1;

  override = new(.full_inst_path(full_inst_path),
                 .orig_type(original_type),
                 .orig_type_name(original_type_name),
                 .ovrd_type(override_type));

  // 如果 original_type 不为空，则表示 original_type_name 不包含通配符
  // ====================================================== //
  // 如果 full_inst_path 包含通配符，会在后面查找 override       //
  // 信息时候处理，这里不进行额外判断                             //
  // ====================================================== //
  if(original_type != null) begin
    if (check_inst_override_exists(original_type,override_type,full_inst_path))
      return;
    if(!m_inst_override_queues.exists(original_type))
      m_inst_override_queues[original_type] = new;
    m_inst_override_queues[original_type].queue.push_back(override);
  end 
  else begin
    // ====================================================== //
    // 如果 original_type_name 包含通配符，则遍历所有注册的类型     //
    // 如果匹配则递归调用当前函数，给所有符合条件的类型设置 override   //
    // ====================================================== //
    if(m_has_wildcard(original_type_name)) begin
       foreach(m_type_names[i]) begin
         if(uvm_is_match(original_type_name,i)) begin
           this.set_inst_override_by_name(i, override_type_name, full_inst_path);
         end
       end
       m_wildcard_inst_overrides.push_back(override);
    end
    else begin
      if(!m_inst_override_name_queues.exists(original_type_name))
        m_inst_override_name_queues[original_type_name] = new;
      m_inst_override_name_queues[original_type_name].queue.push_back(override);
    end
  end

endfunction
```

---

check_inst_override_exists

* 获取到当前需要override的类的信息队列，遍历查找是否存在和当前路径相同的实例override信息
* 如果信息完全对应，则表示当前想要进行的override已经在之前操作过了，所以直接退出

```systemverilog
// Function to check if an instance override already exists
function bit uvm_default_factory::check_inst_override_exists (uvm_object_wrapper original_type,
                                      uvm_object_wrapper override_type,
                                      string full_inst_path);
  uvm_factory_override override;
  uvm_factory_queue_class qc;

  // Check if there's an override queue for the original type
  if (m_inst_override_queues.exists(original_type))
    qc = m_inst_override_queues[original_type];
  else
    return 0; // No override queue exists, so no override exists

  // Iterate through all overrides in the queue
  for (int index=0; index<qc.queue.size(); ++index) begin
    override = qc.queue[index]; 
    // Check if all override details match
    if (
        // Check if the full instance path matches exactly
        override.full_inst_path == full_inst_path &&

        // Verify that the original type object is the same
        override.orig_type == original_type &&

        // Ensure the override type object matches
        override.ovrd_type == override_type &&

        // Confirm that the original type name matches the name of the original type object
        override.orig_type_name == original_type.get_type_name()
    ) begin
      // Report that a duplicate override was found
      uvm_report_info("DUPOVRD",{"Instance override for '",
         original_type.get_type_name(),"' already exists: override type '",
         override_type.get_type_name(),"' with full_inst_path '",
         full_inst_path,"'"},UVM_HIGH);
      return 1; // Override exists
    end
  end
  return 0; // No matching override found
endfunction
```

