  * name="abc", parent.name="def", contxt="gh":
    * full_inst_path = gh.abc
  * name="abc", parent.name="def", contxt="":
    * full_inst_path = def.abc
  * name="abc", parent=null, contxt="":
    * full_inst_path = abc
  * name="", parent.name="def", contxt="gh":
    * full_inst_path = gh
  * name="abc", parent.name="def", contxt="":
    * full_inst_path = def

* 查找是否当前类已经被重写，最后调用[uvm_object_registry:create_object](https://github.com/jiru1997/VLSI-Design-verification-interview/blob/main/VLSI%20Design%20Verification/Functional%20Verification/UVM1.2%20source%20code%20analysis/03:%20uvm_base/chapter%2002:%20uvm_object_registry.md)返回一个实例对象。如果想对 object instance 进行重写，那么必须保证这里得到的最终路径和 [uvm_object_registry:set_inst_override](https://github.com/jiru1997/VLSI-Design-verification-interview/blob/main/VLSI%20Design%20Verification/Functional%20Verification/UVM1.2%20source%20code%20analysis/03:%20uvm_base/chapter%2002:%20uvm_object_registry.md) 中相同

```systemverilog
function uvm_object uvm_default_factory::create_object_by_type (uvm_object_wrapper requested_type,  
                                                        string parent_inst_path="",  
                                                        string name=""); 

  string full_inst_path;

  if (parent_inst_path == "")
    full_inst_path = name;
  else if (name != "")
    full_inst_path = {parent_inst_path,".",name};
  else
    full_inst_path = parent_inst_path;

  //先清空队列，这个队列用来记录 override circle 信息
  m_override_info.delete();

  requested_type = find_override_by_type(requested_type, full_inst_path);

  return requested_type.create_object(name);

endfunction
