* 调用 [m_add_child]() 将当前的 class 添加到父类的子节点列表中

  <img width="550" alt="image" src="https://github.com/jiru1997/VLSI-Design-verification-interview/assets/66343787/4d9b5f1c-6cb5-4aaf-a1f5-613fee9225ec">

* 如果通过 factory 的方式创建对象，那么在创建之前还没有形成完整的层次结构，因此需要传入参数 parent，只有调用了 new 之后，层次结构才完整

```systemverilog
function uvm_component::new (string name, uvm_component parent);
  string error_str;
  uvm_root top;
  uvm_coreservice_t cs;

  super.new(name);

  // ======================================================== //
  // if we are creating uvm_root, set the name to ""          //
  // ======================================================== //
  if (parent==null && name == "__top__") begin
    set_name(""); // *** VIRTUAL
    return;
  end

  cs = uvm_coreservice_t::get();
  top = cs.get_root();  

  // ======================================================== //
  // Check that we're not in or past build_phase              //
  // ======================================================== //
  begin
    uvm_phase bld;
    uvm_domain common;
    common = uvm_domain::get_common_domain();
    bld = common.find(uvm_build_phase::get());
    if (bld == null)
      uvm_report_fatal("COMP/INTERNAL",
                       "attempt to find build phase object failed",UVM_NONE);
    if (bld.get_state() == UVM_PHASE_DONE) begin
      uvm_report_fatal("ILLCRT", {"It is illegal to create a component ('",
                name,"' under '",
                (parent == null ? top.get_full_name() : parent.get_full_name()),
               "') after the build phase has ended."},
                       UVM_NONE);
    end
  end

  // ======================================================== //
  // set default name if name is empty                        //
  // ======================================================== //
  if (name == "") begin
    name.itoa(m_inst_count);
    name = {"COMP_", name};
  end

  // ======================================================== //
  // parent cannot be itself                                  //
  // ======================================================== //
  if(parent == this) begin
    `uvm_fatal("THISPARENT", "cannot set the parent of a component to itself")
  end

  // ======================================================== //
  // set the parent as uvm_root                               //
  // ======================================================== //
  if (parent == null)
    parent = top;

  if(uvm_report_enabled(UVM_MEDIUM+1, UVM_INFO, "NEWCOMP"))
    `uvm_info("NEWCOMP", {"Creating ",
      (parent==top?"uvm_top":parent.get_full_name()),".",name},UVM_MEDIUM+1)

  // ======================================================== //
  // check if the name is unique                              //
  // ======================================================== //
  if (parent.has_child(name) && this != parent.get_child(name)) begin
    if (parent == top) begin
      error_str = {"Name '",name,"' is not unique to other top-level ",
      "instances. If parent is a module, build a unique name by combining the ",
      "the module name and component name: $sformatf(\"\%m.\%s\",\"",name,"\")."};
      `uvm_fatal("CLDEXT",error_str)
    end
    else
      `uvm_fatal("CLDEXT",
        $sformatf("Cannot set '%s' as a child of '%s', %s",
                  name, parent.get_full_name(),
                  "which already has a child by that name."))
    return;
  end

  m_parent = parent;

  // ======================================================== //
  // set the name of the component                            //
  // ======================================================== //
  set_name(name); // *** VIRTUAL

  if (!m_parent.m_add_child(this))
    m_parent = null;

  event_pool = new("event_pool");

  m_domain = parent.m_domain;     // by default, inherit domains from parents

  // Now that inst name is established, reseed (if use_uvm_seeding is set)
  reseed();

  // Do local configuration settings
  if (!uvm_config_db #(uvm_bitstream_t)::get(this, "", "recording_detail", recording_detail))
        void'(uvm_config_db #(int)::get(this, "", "recording_detail", recording_detail));

  //uvm_report_handler m_rh;
  m_rh.set_name(get_full_name());
  set_report_verbosity_level(parent.get_report_verbosity_level());

  m_set_cl_msg_args();

endfunction
```

