uvm_sequence_state

* CREATED 表示此 sequence 已经实例化，接下来从 PRE_START 一直到 POST_START 其实是代表 5 个不同的 task 或者 function:pre_start，pre_body，body，post_body，post_start 等。STOPPED 则是表示一种不正常的中止，FINISHED 表示正常的结束。
```systemverilog
// Defines the current state of a sequence
//
// UVM_CREATED    - Sequence has been allocated
// UVM_PRE_START  - pre_start() task is executing
// UVM_PRE_BODY   - pre_body() task is executing  
// UVM_BODY       - body() task is executing
// UVM_ENDED      - body() task has completed
// UVM_POST_BODY  - post_body() task is executing
// UVM_POST_START - post_start() task is executing
// UVM_STOPPED    - Sequence forcibly ended via kill()
// UVM_FINISHED   - Sequence has completely finished executing

typedef enum {
  UVM_CREATED    = 1,   // Initial state after allocation
  UVM_PRE_START  = 2,   // Executing pre_start() 
  UVM_PRE_BODY   = 4,   // Executing pre_body()
  UVM_BODY       = 8,   // Executing body()
  UVM_ENDED      = 64,  // body() completed
  UVM_POST_BODY  = 16,  // Executing post_body()
  UVM_POST_START = 32,  // Executing post_start()
  UVM_STOPPED    = 128, // Forcibly ended
  UVM_FINISHED   = 256  // Completely finished
} uvm_sequence_state;

// Typedef for backward compatibility
typedef uvm_sequence_state uvm_sequence_state_enum;

typedef enum
{
  UVM_CREATED   = 1,
  UVM_PRE_START = 2,
  UVM_PRE_BODY  = 4,
  UVM_BODY      = 8,
  UVM_POST_BODY = 16,
  UVM_POST_START= 32,
  UVM_ENDED     = 64,
  UVM_STOPPED   = 128,
  UVM_FINISHED  = 256
} uvm_sequence_state;

typedef uvm_sequence_state uvm_sequence_state_enum; // backward compat
```

