local function UVM_FILE get_severity_id_file(uvm_severity severity, string id);

  uvm_id_file_array array;

  // Check if there's a file handle for the specific severity-id combination
  if(severity_id_file_handles.exists(severity)) begin
    array = severity_id_file_handles[severity];      
    if(array.exists(id))
      return array.get(id);
  end

  // If no severity-id specific file handle, check for an id-specific file handle
  if(id_file_handles.exists(id))
    return id_file_handles.get(id);

  // If no id-specific file handle, check for a severity-specific file handle
  if(severity_file_handles.exists(severity))
    return severity_file_handles[severity];

  // If no specific file handle is found, return the default file handle
  return default_file_handle;

endfunction
