Simulation Control

- Can trigger simulation exit (UVM_EXIT) or stop (UVM_STOP)

```systemverilog
  virtual function void execute_report_message(uvm_report_message report_message,
                                               string composed_message);

                                               process p = process::self();

    // Update counts for severity and ID
    incr_severity_count(report_message.get_severity());
    incr_id_count(report_message.get_id());

    // If global recording is enabled, set the RECORD action for this message
    if (record_all_messages)
      report_message.set_action(report_message.get_action() | UVM_RM_RECORD);

    // ========================================================
    // Handle UVM_RM_RECORD action                    
    // ========================================================
    if(report_message.get_action() & UVM_RM_RECORD) begin
       uvm_tr_stream stream;
       uvm_report_object ro = report_message.get_report_object();
       uvm_report_handler rh = report_message.get_report_handler();

       // Check for existing stream
       if (m_streams.exists(ro.get_name()) && (m_streams[ro.get_name()].exists(rh.get_name())))
         stream = m_streams[ro.get_name()][rh.get_name()];

       // Create new stream if needed
       if (stream == null) begin
          uvm_tr_database db;

          // Get the message database
          db = get_message_database();

          // Use default database if none specified
          if (db == null) begin
             uvm_coreservice_t cs = uvm_coreservice_t::get();
             db = cs.get_default_tr_database();
          end
          if (db != null) begin
             // Open a new stream
             stream = db.open_stream(ro.get_name(), rh.get_name(), "MESSAGES");
             // Store the opened stream
             m_streams[ro.get_name()][rh.get_name()] = stream;
          end
       end
       // Record the message if stream is available
       if (stream != null) begin
          uvm_recorder recorder = stream.open_recorder(report_message.get_name(),,report_message.get_type_name());
             if (recorder != null) begin
             report_message.record(recorder);
             recorder.free();
          end
       end
    end

    // ========================================================
    // Handle UVM_DISPLAY action
    // ========================================================
    if(report_message.get_action() & UVM_DISPLAY)
      $display("%s", composed_message);

    // ========================================================
    // Handle UVM_LOG action
    // ========================================================
    // Handle UVM_LOG action
    if(report_message.get_action() & UVM_LOG) begin
      // Check if the file is valid and not stdout (32'h8000_0001)
      if((report_message.get_file() == 0) || 
         (report_message.get_file() != 32'h8000_0001)) begin

        // get the file handle
        UVM_FILE tmp_file = report_message.get_file();

        // Check if the file is an MCD (Multi-Channel Descriptor)
        // The purpose of masking off bit 0 (stdout) is to prevent duplicate output. If bit 0 were set in the original MCD, 
        // it would have been cleared by this operation, ensuring the message doesn't also go to stdout when it's already 
        // being sent to specific MCD channels.

        if((report_message.get_file() & 32'h8000_0000) == 0) begin
          // If it's an MCD, mask off stdout (bit 0) to avoid duplicate output
          tmp_file = report_message.get_file() & 32'hffff_fffe;
        end

        // Display the message to the specified file
        f_display(tmp_file, composed_message);
      end
    end

    // ========================================================
    // Handle UVM_COUNT action
    // ========================================================
    if(report_message.get_action() & UVM_COUNT) begin
      // Check if max_quit_count is set (non-zero)
      if(get_max_quit_count() != 0) begin
        // Increment the quit count
        incr_quit_count();
        // Check if the quit count has reached the maximum
        if(is_quit_count_reached()) begin
          // If max quit count is reached, add UVM_EXIT action to the message
          report_message.set_action(report_message.get_action() | UVM_EXIT);
        end
      end  
    end

    // ======================================================== 
    // Handle UVM_EXIT action
    // ========================================================
    if(report_message.get_action() & UVM_EXIT) begin
       uvm_root l_root;
       uvm_coreservice_t cs;
       cs = uvm_coreservice_t::get();
       l_root = cs.get_root();
       // execute $finish
       l_root.die();
    end

    // ======================================================== 
    // Handle UVM_STOP action
    // ========================================================
    if (report_message.get_action() & UVM_STOP) 
      $stop;

  endfunction
