sprint

* 将当前对象以字符串的形式返回，先将已经注册过的 attribute 打印出来，然后调用 do_print 打印未注册的 attribute

```systemverilog
function string uvm_object::sprint(uvm_printer printer=null);
  bit p;

  // If no printer is provided, use the default printer
  if(printer==null)
    printer = uvm_default_printer;

  // Check if we're not at the top level of printing (i.e., recursing into a sub-object)
  if(!printer.istop()) begin
    // Set the current printer in the status container
    __m_uvm_status_container.printer = printer;

    // Call field automation for printing
    // print all attributes of the object if they are registered
    __m_uvm_field_automation(null, UVM_PRINT, "");

    // Call the object-specific print method
    do_print(printer);

    // Return an empty string as we're not at the top level
    return "";
  end

  // We are at the top level, so print the object
  printer.print_object(get_name(), this);

  // Check for backward compatibility with the sprint knob
  // If m_string is not empty, it means the old sprint method was used
  if (printer.m_string != "")
    return printer.m_string;

  // If not using the old sprint method, emit the printer's contents
  return printer.emit();

endfunction
