print_msg

* 从 __m_uvm_status_container 的 scope 得到刚刚放进去的字符串并打印

```systemverilog
function void print_msg_object(uvm_object lhs, uvm_object rhs);
  uvm_root root;
  uvm_coreservice_t cs;
  cs = uvm_coreservice_t::get();
  root = cs.get_root();

  result++;
  if(result <= show_max) begin
     root.uvm_report(sev, "MISCMP",
       $sformatf("Miscompare for %0s: lhs = @%0d : rhs = @%0d",
       uvm_object::__m_uvm_status_container.scope.get(), (lhs!=null ? lhs.get_inst_id() : 0),
                   (rhs != null ? rhs.get_inst_id() : 0)), verbosity, `uvm_file, `uvm_line);
  end
  $swrite(miscompares, "%s%s: lhs = @%0d : rhs = @%0d",
      miscompares, uvm_object::__m_uvm_status_container.scope.get(),
      (lhs != null ? lhs.get_inst_id() : 0), (rhs != null ? rhs.get_inst_id() : 0));
endfunction
```
