      root.uvm_report(sev, "MISCMP", $sformatf("%s%s@%0d vs. %s@%0d", msg,
                      lhs.get_name(), lhs.get_inst_id(), rhs.get_name(), rhs.get_inst_id()),
    verbosity, `uvm_file, `uvm_line);
    end
  end
endfunction
