sort_by_precedence

```systemverilog
// Sort resources by precedence
static function void sort_by_precedence(ref uvm_resource_types::rsrc_q_t q);
  uvm_resource_types::rsrc_q_t all[int];
  uvm_resource_base r;

  // Group resources by precedence
  for(int i=0; i<q.size(); ++i) begin
    r = q.get(i);
    if(!all.exists(r.precedence))
      all[r.precedence] = new;
    // Add to front of precedence group (will be reversed later)
    all[r.precedence].push_front(r);
  end

  // Clear original queue
  q.delete();

  // Rebuild queue in precedence order
  foreach(all[i]) begin
    for(int j=0; j<all[i].size(); ++j) begin
      r = all[i].get(j);
      // Add to front to reverse order within each precedence group
      q.push_front(r);
    end
  end
endfunction
```
