m_check_relationship

* 被 [connect]() 调用，检查端口类型之间的关系
   * from => 当前端口
   * from_parent => 当前端口的父component
   * from_gparent => 当前端口的祖先component
   * provider => IMP端点
   * to_parent => IMP端点的父component
   * to_gparent => IMP端点的祖先component

* 两个port相连,用于父子连接(child -> parent) => ***child_component.child_port.connect(parent_port)***
* export和export/import相连,用于父子连接(parent -> child) => ***parent_export.connect(child_component.child_export)***
* port和export/import相连，用于同级连接 => ***component1.port.connect(component2.export)***

  <img width="700" alt="image" src="https://github.com/jiru1997/VLSI-Design-verification-interview/assets/66343787/2a327489-75ff-44c1-b021-799e51c85b6f">


```systemverilog
local function bit  m_check_relationship (this_type provider);  
 string s;
 this_type from;
 uvm_component from_parent;
 uvm_component to_parent;
 uvm_component from_gparent;
 uvm_component to_gparent;

 // Checks that the connection is between ports that are hierarchically
 // adjacent (up or down one level max, or are siblings),
 // and check for legal direction, requirer.connect(provider).

 // if we're an analysis port, allow connection to anywhere
 if (get_type_name() == "uvm_analysis_port")
   return 1;

 from         = this;
 from_parent  = get_parent();
 to_parent    = provider.get_parent();

 // skip check if we have a parentless port
 if (from_parent == null || to_parent == null)
   return 1;

 from_gparent = from_parent.get_parent();
 to_gparent   = to_parent.get_parent();

 // Connecting port-to-port: CHILD.port.connect(PARENT.port)
 //
 if (from.is_port() && provider.is_port() && from_gparent != to_parent) begin
   s = {provider.get_full_name(),
        " (of type ",provider.get_type_name(),
        ") is not up one level of hierarchy from this port. ",
        "A port-to-port connection takes the form ",
        "child_component.child_port.connect(parent_port)"};
   m_comp.uvm_report_warning(s_connection_warning_id, s, UVM_NONE);
   return 0;
 end    

 // Connecting port-to-export: SIBLING.port.connect(SIBLING.export)
 // Connecting port-to-imp:    SIBLING.port.connect(SIBLING.imp)
 else if (from.is_port() && (provider.is_export() || provider.is_imp()) &&
          from_gparent != to_gparent) begin
     s = {provider.get_full_name(),
        " (of type ",provider.get_type_name(),
        ") is not at the same level of hierarchy as this port. ",
        "A port-to-export connection takes the form ",
        "component1.port.connect(component2.export)"};
   m_comp.uvm_report_warning(s_connection_warning_id, s, UVM_NONE);
   return 0;
 end

 // Connecting export-to-export: PARENT.export.connect(CHILD.export)
 // Connecting export-to-imp:    PARENT.export.connect(CHILD.imp)
 else if (from.is_export() && (provider.is_export() || provider.is_imp()) &&
          from_parent != to_gparent) begin
   s = {provider.get_full_name(),
        " (of type ",provider.get_type_name(),
        ") is not down one level of hierarchy from this export. ",
        "An export-to-export or export-to-imp connection takes the form ",
        "parent_export.connect(child_component.child_export)"};
   m_comp.uvm_report_warning(s_connection_warning_id, s, UVM_NONE);
   return 0;
 end

 return 1;
endfunction
