  0: imp1 (uvm_analysis_imp #(transaction))
  1: imp2 (uvm_analysis_imp #(transaction))
```

* Function Analysis:
  * It uses recursion to traverse the entire network of connected ports.
  * It builds a string representation (save) of the network structure.
  * It handles indentation to create a tree-like visual structure.
  * For the top-level call (when level == 0), it adds additional information about resolved implementations.

```systemverilog
function void debug_connected_to (int level=0, int max_level=-1);
  int sz, num, curr_num;
  string s_sz;
  static string indent, save;
  this_type port;

  // Initialize level and indentation for top-level call
  if (level <  0) level = 0;
  if (level == 0) begin save = ""; indent="  "; end

  // Check if we've reached the maximum depth to display
  if (max_level != -1 && level >= max_level)
    return;

  num = m_provided_by.num();

  // Recursively display the fanout network
  if (m_provided_by.num() != 0) begin
    foreach (m_provided_by[nm]) begin
      curr_num++;
      port = m_provided_by[nm];
      save = {save, indent, "  | \n"};
      save = {save, indent, "  |_",nm," (",port.get_type_name(),")\n"};
      // Adjust indentation for child ports
      indent = (num > 1 && curr_num != num) ?  {indent,"  | "}:{indent, "    "};
      port.debug_connected_to(level+1, max_level);
      indent = indent.substr(0,indent.len()-4-1);
    end
  end

  // For top-level call, finalize and display the output
  if (level == 0) begin
    if (save != "")
      save = {"This port's fanout network:\n\n  ",
             get_full_name()," (",get_type_name(),")\n",save,"\n"};

    // Check if implementations are resolved
    if (m_imp_list.num() == 0) begin
      uvm_root top;
      uvm_coreservice_t cs;
      cs = uvm_coreservice_t::get();
      top = cs.get_root();
      if (end_of_elaboration_ph.get_state() == UVM_PHASE_EXECUTING ||
          end_of_elaboration_ph.get_state() == UVM_PHASE_DONE )  // TBD tidy
         save = {save,"  Connected implementations: none\n"};
      else
         save = {save,
               "  Connected implementations: not resolved until end-of-elab\n"};
    end
    else begin
      // Display resolved implementations
      save = {save,"  Resolved implementation list:\n"};
      foreach (m_imp_list[nm]) begin
        port = m_imp_list[nm];
        s_sz.itoa(sz);
        save = {save, indent, s_sz, ": ",nm," (",port.get_type_name(),")\n"};
        sz++;
      end
    end
    m_comp.uvm_report_info("debug_connected_to", save);
  end
endfunction
