```systemverilog
function uvm_port_base #(IF) get_if(int index=0);
  string s;

  // Check if the port has any connections
  if (size()==0) begin
    m_comp.uvm_report_warning("get_if",
      "Port size is zero; cannot get interface at any index", UVM_NONE);
    return null;
  end

  // Check if the provided index is within valid range
  if (index < 0 || index >= size()) begin
    $sformat(s, "Index %0d out of range [0,%0d]", index, size()-1);
    m_comp.uvm_report_warning(s_connection_error_id, s, UVM_NONE);
    return null;
  end

  // Iterate through the implementation list to find the requested index
  foreach (m_imp_list[nm]) begin
    if (index == 0)
      return m_imp_list[nm];  // Return the implementation at the requested index
    index--;  // Decrement index as we iterate
  end

  // This point should never be reached if index is valid
  // Return null implicitly if no implementation found
endfunction
