```systemverilog
// Function to set a resource in the resource database
static function void set(input string scope, input string name,
                         T val, input uvm_object accessor = null);

  // Create a new resource with the given name and scope
  rsrc_t rsrc = new(name, scope);

  // Write the value to the object and accessor to the resource
  rsrc.write(val, accessor);

  // Set the resource in the resource pool
  rsrc.set();

  // If tracing is enabled, show a message with the resource details
  if(uvm_resource_db_options::is_tracing())
    m_show_msg("RSRCDB/SET", "Resource","set", scope, name, accessor, rsrc);
endfunction
