m_drop

* 调用[drop_objection]()
* **m_source_count 用来记录当前 obj 自己 raise 的 objection 的个数；m_total_count 用来记录自己以及子节点 raise 的所有 objection 的个数**
```systemverilog
protected int     m_source_count[uvm_object];
protected int     m_total_count [uvm_object];

protected uvm_root m_top;
```

* 进行两次检查：
  * 检查当前 obj 所有 objection 个数，如果小于传入的想要 drop 的个数，则报错
  * 如果当前 obj 是 source_obj 还要再检查由自己 raise 的 objection 的个数，如果小于传入的想要 drop 的个数，则报错

* 调用 [dropped]()，没有实际的实现，需要用户重写回调函数
* 如果当前 obj 中还有 raised objection(m_total_count[obj] != 0):
  * 如果是跳步(m_prop_mode=0):
    * 直接将 obj 更新成 uvm_root，递归调用当前函数，将 uvm_root 中的 objection drop
  * 如果不是跳步
    * 调用 [m_propagate]()，将 obj 更新成 parent obj，递归关闭 parent obj 中的 objection

* 如果当前 obj 中没有 raised objection:
  * 使用当前节点的信息创建一个对象，并存储到 m_scheduled_list 中，通过[m_execute_scheduled_forks]() -> [m_forked_drain]() 路径，**先执行完这个 obj 的 drain time**，再将其从 m_source_count/m_total_count 中彻底删除，最后再递归 parent obj
  * 这样执行是为了可以支持给所有不同的 component 添加 drain time

```systemverilog
 function void m_drop (uvm_object obj,
                        uvm_object source_obj,
                        string description="",
                        int count=1,
                        int in_top_thread=0);

    // Ignore drops if the count is 0
    if (count == 0)
      return;

    // 检查已经 raise 的 objection 的个数
    if (!m_total_count.exists(obj) || (count > m_total_count[obj])) begin
      if(m_cleared)
        return;
      uvm_report_fatal("OBJTN_ZERO", {"Object \"", obj.get_full_name(), 
        "\" attempted to drop objection '",this.get_name(),"' count below zero"});
      return;
    end

    // 如果发起的 obj 是自己，还要检查由自己发起的 objection 的个数
    if (obj == source_obj) begin
      if (!m_source_count.exists(obj) || (count > m_source_count[obj])) begin
        if(m_cleared)
          return;
        uvm_report_fatal("OBJTN_ZERO", {"Object \"", obj.get_full_name(), 
          "\" attempted to drop objection '",this.get_name(),"' count below zero"});
        return;
      end
      m_source_count[obj] -= count;
    end

    // udpate the objection count
    m_total_count[obj] -= count;

    if (m_trace_mode)
      m_report(obj,source_obj,description,count,"dropped");

    dropped(obj, source_obj, description, count);

    // if count != 0, no reason to fork
    if (m_total_count[obj] != 0) begin
      if (!m_prop_mode && obj != m_top)
        m_drop(m_top,source_obj,description, count, in_top_thread);
      else if (obj != m_top) begin
        this.m_propagate(obj, source_obj, description, count, 0, in_top_thread);
      end

    end
    else begin
        uvm_objection_context_object ctxt;
        if (m_context_pool.size())
          ctxt = m_context_pool.pop_front();
        else
          ctxt = new;

        ctxt.obj = obj;
        ctxt.source_obj = source_obj;
        ctxt.description = description;
        ctxt.count = count;
        ctxt.objection = this;
        // Need to be thread-safe, let the background
        // process handle it.

        // Why don't we look at in_top_thread here?  Because
        // a re-raise will kill the drain at object that it's
        // currently occuring at, and we need the leaf-level kills
        // to not cause accidental kills at branch-levels in
        // the propagation.

        // Using the background process just allows us to
        // separate the links of the chain.
        m_scheduled_list.push_back(ctxt);

    end // else: !if(m_total_count[obj] != 0)

  endfunction
```

