pack_object

* 这个函数被 [uvm_field_object]() 调用，传入一个 Object 类型的参数, 这里再递归调用 [__m_uvm_field_automation]()，将当前 object 中注册过的每一个 field 进行 pack
* 这个函数不能单独调用，如果单独调用，当在 __m_uvm_field_automation 中，packer 并没有设置，可能会造成 null pointer 的错误，通常情况都是在 [uvm_object:pack]() 调用，会在调用的过程中设置好 packer, __m_uvm_status_container 是一个 static 的变量，说明所有的 object 公用一个 container 并且贡献其中的 packer, printer, comparer, recorder，所以只需要设置一次就可以递归使用，保证使用的是同一个 packer，因此可以写入到同一个 m_bits 数组中

```systemverilog
function void uvm_packer::pack_object(uvm_object value);

  // Check for cyclic references
  if(value.__m_uvm_status_container.cycle_check.exists(value)) begin
    uvm_report_warning("CYCFND", $sformatf("Cycle detected for object @%0d during pack", value.get_inst_id()), UVM_NONE);
    return;
  end

  // Mark object as visited
  value.__m_uvm_status_container.cycle_check[value] = 1;

  if((policy != UVM_REFERENCE) && (value != null)) begin
    // Pack object if not using reference policy and object is not null
    if(use_metadata == 1) begin
      // Set metadata flag
      m_bits[count +: 4] = 1;
      count += 4; // Increment count for better debugging when displaying packed bits in hexadecimal
    end

    // Enter object scope
    scope.down(value.get_name());

    // Perform packing
    // pack all fields of the object which is registered with uvm_field_macros
    value.__m_uvm_field_automation(null, UVM_PACK,"");
    value.do_pack(this);

    // Exit object scope
    scope.up();
  end
  else if(use_metadata == 1) begin
    // Set metadata flag to 0 if not packing object
    m_bits[count +: 4] = 0;
    count += 4;
  end

  // Remove object from cycle check
  value.__m_uvm_status_container.cycle_check.delete(value);
endfunction
```

---

unpack_object

```systemverilog
function void uvm_packer::unpack_object(uvm_object value);
  byte is_non_null = 1;

  // Check for cyclic references
  if (value.__m_uvm_status_container.cycle_check.exists(value)) begin
    uvm_report_warning("CYCFND", 
      $sformatf("Cycle detected for object @%0d during unpack", value.get_inst_id()), 
      UVM_NONE);
    return;
  end

  // Mark object as visited
  value.__m_uvm_status_container.cycle_check[value] = 1;

  // Handle metadata if enabled
  if (use_metadata == 1) begin
    is_non_null = m_bits[count +: 4];
    count += 4;
  end

  // Unpack object if it's not null and metadata indicates it's non-null
  if (value != null) begin
    if (is_non_null > 0) begin
      scope.down(value.get_name());
      value.__m_uvm_field_automation(null, UVM_UNPACK, "");
      value.do_unpack(this);
      scope.up();
    end
    // TODO: Implement logic for null unpacked results
  end
  // Error handling for attempting to unpack into a null object
  else if ((is_non_null != 0) && (value == null)) begin
    uvm_report_error("UNPOBJ", "Cannot unpack into null object", UVM_NONE);
  end

  // Remove object from cycle check
  value.__m_uvm_status_container.cycle_check.delete(value);
endfunction
```

