```systemverilog
function void uvm_packer::pack_bytes(ref byte value[], input int size = -1);
   int max_size = value.size() * $bits(byte);

   if (size < 0)
     size = max_size;

   if (size > max_size) begin
      `uvm_error("UVM/BASE/PACKER/BAD_SIZE",
                 $sformatf("pack_bytes called with size '%0d', which exceeds value size of '%0d'",
                           size,
                           max_size))
      return;
   end
   else begin
      // idx_select is used to determine which byte and bit to access, considering the endianness.
      // value[idx_select / $bits(byte)] selects the byte from the input array.
      // [idx_select % $bits(byte)] selects the specific bit within that byte.
      // The result is stored in m_bits[count+i], which is a bit array.
      int idx_select;

      for (int i=0; i<size; i++) begin
         if (big_endian == 1)
           idx_select = size-1-i;
         else
           idx_select = i;

         m_bits[count+i] = value[idx_select / $bits(byte)][idx_select % $bits(byte)];
      end

      count += size;

      // =================================================================== //
      // Example:                                                            //
      // byte value[] = '{8'b10101010, 8'b11001100, 8'b11110000};            //
      // size = 24 (3 bytes * 8 bits)                                        //
      //                                                                     //
      // Case 1: big_endian = 0 (little-endian)                              //
      //                                                                     //
      // i=0:  idx_select=0,  value[0][0] = 0 -> m_bits[count+0] = 0         //
      // i=1:  idx_select=1,  value[0][1] = 1 -> m_bits[count+1] = 1         //
      // i=2:  idx_select=2,  value[0][2] = 0 -> m_bits[count+2] = 0         //
      // i=3:  idx_select=3,  value[0][3] = 1 -> m_bits[count+3] = 1         //
      // i=4:  idx_select=4,  value[0][4] = 0 -> m_bits[count+4] = 0         //
      // i=5:  idx_select=5,  value[0][5] = 1 -> m_bits[count+5] = 1         //
      // i=6:  idx_select=6,  value[0][6] = 0 -> m_bits[count+6] = 0         //
      // i=7:  idx_select=7,  value[0][7] = 1 -> m_bits[count+7] = 1         //
      // i=8:  idx_select=8,  value[1][0] = 0 -> m_bits[count+8] = 0         //
      // i=9:  idx_select=9,  value[1][1] = 0 -> m_bits[count+9] = 0         //
      // i=10: idx_select=10, value[1][2] = 1 -> m_bits[count+10] = 1        //
      // i=11: idx_select=11, value[1][3] = 1 -> m_bits[count+11] = 1        //
      // i=12: idx_select=12, value[1][4] = 0 -> m_bits[count+12] = 0        //
      // i=13: idx_select=13, value[1][5] = 0 -> m_bits[count+13] = 0        //
      // i=14: idx_select=14, value[1][6] = 1 -> m_bits[count+14] = 1        //
      // i=15: idx_select=15, value[1][7] = 1 -> m_bits[count+15] = 1        //
      // i=16: idx_select=16, value[2][0] = 0 -> m_bits[count+16] = 0        //
      // i=17: idx_select=17, value[2][1] = 0 -> m_bits[count+17] = 0        //
      // i=18: idx_select=18, value[2][2] = 0 -> m_bits[count+18] = 0        //
      // i=19: idx_select=19, value[2][3] = 0 -> m_bits[count+19] = 0        //
      // i=20: idx_select=20, value[2][4] = 1 -> m_bits[count+20] = 1        //
