* **大端模式的情况下是，直接对数组做位截取得到的结果和原始数据正好相反，所以在解析时候，先做截取再反向读取数据**

```systemverilog
function void uvm_packer::pack_ints(ref int value[], input int size = -1);
   int max_size = value.size() * $bits(int);

   if (size < 0)
     size = max_size;

   if (size > max_size) begin
      `uvm_error("UVM/BASE/PACKER/BAD_SIZE",
                 $sformatf("pack_ints called with size '%0d', which exceeds value size of '%0d'",
                           size,
                           max_size))
      return;
   end
   else begin
      int idx_select;

      for (int i=0; i<size; i++) begin
         if (big_endian == 1)
           idx_select = size-1-i;
         else
           idx_select = i;

         m_bits[count+i] = value[idx_select / $bits(int)][idx_select % $bits(int)];
      end

      count += size;

      // ==================================================================== //
      // int value[] = '{32'hA5A5_A5A5, 32'h3C3C_3C3C, 32'hF0F0_F0F0};        //
      //                                                                      //
      // 1. Little-Endian Packing (big_endian = 0):                           //
      //                                                                      //
      // value[0]        value[1]        value[2]                             //
      // A5A5_A5A5       3C3C_3C3C       F0F0_F0F0                            //
      // |               |               |                                    //
      // v               v               v                                    //
      // 5 A 5 A 5 A 5 A 3 C 3 C 3 C 3 C F 0 F 0 F 0 F 0                      //
      // +----+----+----+----+----+----+----+----+----+----+----+----+        //
      // |1010|0101|1010|0101|0011|1100|0011|1100|1111|0000|1111|0000|        //
      // +----+----+----+----+----+----+----+----+----+----+----+----+        //
      // 0    8    16   24   32   40   48   56   64   72   80   88   95       //
      //                                                                      //
      // LSB of A5 (1010 0101) is at bit position 0 in m_bits array           //
      //                                                                      //
      // 2. Big-Endian Packing (big_endian = 1):                              //
      //                                                                      //
      // value[2]        value[1]        value[0]                             //
      // F0F0_F0F0       3C3C_3C3C       A5A5_A5A5                            //
      // |               |               |                                    //
      // v               v               v                                    //
      // F 0 F 0 F 0 F 0 3 C 3 C 3 C 3 C 5 A 5 A 5 A 5 A                      //
      // +----+----+----+----+----+----+----+----+----+----+----+----+        //
      // |1111|0000|1111|0000|0011|1100|0011|1100|1010|0101|1010|0101|        //
      // +----+----+----+----+----+----+----+----+----+----+----+----+        //
      // 0    8    16   24   32   40   48   56   64   72   80   88   95       //
      //                                                                      //
      // LSB of A5 (1010 0101) is at bit position 88 in m_bits array          //
      // ==================================================================== //

      // ==================================================================== //
      // int value[] = '{32'hA5A5_A5A5, 32'h3C3C_3C3C, 32'hF0F0_F0F0};        //
      // int size = 96; // 3 integers * 32 bits each                          //
      // bit big_endian = 0; // little-endian                                 //
      //                                                                      //
      // Little-endian case (big_endian = 0):                                 //
      // i=0:   idx_select=0,   value[0][0]  = 1 -> m_bits[count+0]  = 1      //
      // i=1:   idx_select=1,   value[0][1]  = 0 -> m_bits[count+1]  = 0      //
      // i=2:   idx_select=2,   value[0][2]  = 1 -> m_bits[count+2]  = 1      //
      // ...                                                                  //
      // i=31:  idx_select=31,  value[0][31] = 1 -> m_bits[count+31] = 1      //
      // i=32:  idx_select=32,  value[1][0]  = 0 -> m_bits[count+32] = 0      //
      // i=33:  idx_select=33,  value[1][1]  = 0 -> m_bits[count+33] = 0      //
      // ...                                                                  //
      // i=95:  idx_select=95,  value[2][31] = 1 -> m_bits[count+95] = 1      //
      //                                                                      //
      // Big-endian case (if big_endian = 1):                                 //
      // i=0:   idx_select=95,  value[2][31] = 1 -> m_bits[count+0]  = 1      //
      // i=1:   idx_select=94,  value[2][30] = 1 -> m_bits[count+1]  = 1      //
      // i=2:   idx_select=93,  value[2][29] = 1 -> m_bits[count+2]  = 1      //
      // ...                                                                  //
      // i=63:  idx_select=32,  value[1][0]  = 0 -> m_bits[count+63] = 0      //
      // i=64:  idx_select=31,  value[0][31] = 1 -> m_bits[count+64] = 1      //
