function string uvm_packer::unpack_string(int num_chars=-1);

  // ======================================================================= //
  // 1. Little-Endian Case (big_endian = 0):                                 //
  // Initial m_bits: 01010101 01010110 01001101 00000000                     //
  //                 ^                                                       //
  //                 |                                                       //
  //                 count (initially 0)                                     //
  //                                                                         //
  // Unpacking process:                                                      //
  // i=0: unpack_string[0] = 8'b01010101 ('U')                               //
  // i=1: unpack_string[1] = 8'b01010110 ('V')                               //
  // i=2: unpack_string[2] = 8'b01001101 ('M')                               //
  // i=3: Null terminator encountered, stop unpacking                        //
  //                                                                         //
  // Result: unpack_string = "UVM"                                           //
  // Final count: 32 (3 characters * 8 bits + 8 bits for null terminator)    //
  //                                                                         //
  // Big-Endian Case (big_endian = 1):                                       //
  // Initial m_bits: 10101010 01101010 10110010 00000000                     //
  //                 ^                                                       //
  //                 |                                                       //
  //                 count (initially 0)                                     //
  //                                                                         //
  // Unpacking process:                                                      //
  // i=0: unpack_string[0] = 8'b01010101 ('U') (after bit reversal)          //
  // i=1: unpack_string[1] = 8'b01010110 ('V') (after bit reversal)          //
  // i=2: unpack_string[2] = 8'b01001101 ('M') (after bit reversal)          //
  // i=3: Null terminator encountered, stop unpacking                        //
  //                                                                         //
  // Result: unpack_string = "UVM"                                           //
  // Final count: 32 (3 characters * 8 bits + 8 bits for null terminator)    //
  // ======================================================================= //

  byte b;
  bit  is_null_term; // Assumes a ~null~ terminated string
  int i; i=0;

  // is_null_term = 1: 持续读取直到遇到null terminator
  // is_null_term = 0: 读取num_chars个字符
  if(num_chars == -1) is_null_term = 1;
  else is_null_term = 0;

  // ======================================================================= //
  // enough_bits(8,"string")                                                 //
  // This checks if there are at least 8 bits left in the m_bits array to    //
  // unpack. It ensures we don't try to read beyond the end of the packed    //
  // data. The "string" argument is likely used for error reporting if       //
  // there aren't enough bits.                                               //
  //                                                                         //
  // ((m_bits[count+:8] != 0) || (is_null_term == 0))                        //
  // This part handles the null termination logic.                           //
  // m_bits[count+:8] != 0 checks if the next 8 bits are not all zeros       //
  // (not a null terminator).                                                //
  // is_null_term == 0 is true if we're not looking for a null terminator    //
  // (i.e., unpacking a fixed number of characters).                         //
  // The OR (||) means we continue if either we haven't hit a null           //
  // terminator OR we're not using null termination.                         //
  //                                                                         //
  // ((i<num_chars)||(is_null_term==1))                                      //
  // This part handles the character count logic.                            //
  // i<num_chars checks if we've unpacked fewer characters than the          //
  // specified limit.                                                        //
  // is_null_term==1 is true if we're using null termination (ignoring       //
  // num_chars).                                                             //
  // The OR (||) means we continue if either we haven't reached the          //
  // character limit OR we're using null termination.                        //
  // ======================================================================= //

  while(enough_bits(8,"string") && 
        ((m_bits[count+:8] != 0) || (is_null_term == 0)) &&
        ((i<num_chars)||(is_null_term==1)) )
  begin
    // ======================================================= //
    // Initial state:                                          //
    // m_bits = 01010101 01010110 01001101 00000000            //
    //          ^                                              //
    //          |                                              //
    //          count (initially 0)                            //
    // unpack_string = "" (empty string)                       //
    // i = 0                                                   //
    //                                                         //
    // Step-by-step unpacking:                                 //
    //                                                         //
    // Iteration 1:                                            //
    // unpack_string = {unpack_string," "} = " "               //
    // unpack_string[0] = m_bits[0 +: 8] = 01010101 ('U')      //
    // count = 8, i = 1                                        //
    //

