function int get_depth();

  // If depth has been set or calculated, then use that
  if (m_depth != -1) begin
    return (m_depth);
  end

  // Calculate the depth, store it, and return the value
  if (m_parent_sequence == null) begin
    m_depth = 1;
  end else begin
    m_depth = m_parent_sequence.get_depth() + 1;
  end

  return (m_depth);
endfunction 
