flush

```systemverilog
virtual function void flush();
  T t;
  bit r;

  r = 1; 
  while( r ) r = try_get( t ) ;

  if( m.num() > 0 && m_pending_blocked_gets != 0 ) begin
    uvm_report_error("flush failed" ,
         "there are blocked gets preventing the flush", UVM_NONE);
  end

endfunction
