do_read

* 被 [read]() 调用
* 调用[Xcheck_accessX]()，对于 BACKDOOR 来说，检查是否设置了 hdl 路径; 对于 FRONTDOOR 来说，检查是否配置了 uvm_reg_map 

* 给 m_read_in_progress 赋值，标志写操作开始。检查要写入的数据是否超过了此 uvm_reg_field 所能存放的最大数值。如果超过了，给出警告，并且把超过的部分直接忽略，只考虑有效的数值。

* 调用 [uvm_reg_map:do_read]() 读取 reg_field 中的数值

  <img width="650" alt="image" src="https://github.com/jiru1997/VLSI-Design-verification-interview/assets/66343787/e0f78cb9-c320-48b3-8dc5-a326a43f98e3">


* 调用 [do_predict]() 来更新寄存器模型中的值

```systemverilog
task uvm_reg_field::do_read(uvm_reg_item rw);

   uvm_reg_map_info map_info;
   bit bad_side_effect;

   m_parent.XatomicX(1);
   m_fname  = rw.fname;
   m_lineno = rw.lineno;
   m_read_in_progress = 1'b1;

   if (!Xcheck_accessX(rw,map_info,"read()"))
     return;

`ifdef UVM_REG_NO_INDIVIDUAL_FIELD_ACCESS
   rw.element_kind = UVM_REG;
   rw.element = m_parent;
   m_parent.do_read(rw);
   rw.value[0] = (rw.value[0] >> m_lsb) & ((1<<m_size))-1;
   bad_side_effect = 1;
`else

   if (!is_indv_accessible(rw.path,rw.local_map)) begin
      //在不支持按照 field 访问的情况下，把本次 read 操作变更为一次 uvm_reg 的 read 操作
      rw.element_kind = UVM_REG;
      rw.element = m_parent;
      bad_side_effect = 1;
      m_parent.do_read(rw);
      rw.value[0] = (rw.value[0] >> m_lsb) & ((1<<m_size))-1;
   end
   else begin

     uvm_reg_map system_map = rw.local_map.get_root_map();
     uvm_reg_field_cb_iter cbs = new(this);

     //以防止其它程序在 read 操作时执行别的操作，从而出错。这里与 XatomicX 相似，都是为了保证对互斥资源的访问
     m_parent.Xset_busyX(1);

     rw.status = UVM_IS_OK;

     //execute callback functions
     pre_read(rw);
     for (uvm_reg_cbs cb = cbs.first(); cb != null; cb = cbs.next())
        cb.pre_read(rw);

     if (rw.status != UVM_IS_OK) begin
        m_read_in_progress = 1'b0;
        m_parent.Xset_busyX(0);
        m_parent.XatomicX(0);

        return;
     end

     //read field value from rtl
     rw.local_map.do_read(rw);

     //update the value in the register model
     if (system_map.get_auto_predict())
        // ToDo: Call parent.XsampleX();
        do_predict(rw, UVM_PREDICT_READ);

     post_read(rw);
     for (uvm_reg_cbs cb=cbs.first(); cb!=null; cb=cbs.next())
        cb.post_read(rw);

     m_parent.Xset_busyX(0);

   end

`endif

   m_read_in_progress = 1'b0;
   m_parent.XatomicX(0);

   if (bad_side_effect) begin
      uvm_reg_field fields[$];
      m_parent.get_fields(fields);
      foreach (fields[i]) begin
         string mode;
         if (fields[i] == this)
            continue;
         mode = fields[i].get_access();
         if (mode == "RC" ||
             mode == "RS" ||
             mode == "WRC" ||
             mode == "WRS" ||
             mode == "WSRC" ||
             mode == "WCRS" ||
             mode == "W1SRC" ||
             mode == "W1CRS" ||
             mode == "W0SRC" ||
             mode == "W0CRS") begin
            `uvm_warning("RegModel", {"Reading field '",get_full_name(),
                "' will cause unintended side effects in adjoining ",
                "Read-to-Clear or Read-to-Set fields in the same register"})
         end
      end
   end

endtask: do_read
