is_indv_accessible

* 被 [do_write]() 调用，判断是否可以对 field 单独访问，其判断标准是只有 FRONTDOOR 才能进行按照 field 访问; 如果用户定义了自己的 frontdoor，那么是不能按照 field 访问的; 把寄存器位宽(如 64)按照总线宽度(如 16)，分成几个区域，如果此 field 能够独占这个区域，那么是可以按 field 访问的，除此之外都不能按照 field 访问。

* **UVM 中是不支持 BACKDOOR 方式的按照 field 的访问寄存器的，只支持 FRONTDOOR 形式的**。所以如果传入的是 UVM_BACKDOOR 则直接返回。

* 检查 m_individually_accessible 成员变量，这个成员变量的默认值为 0，它在调用 [configure]() 函数时被赋值。因此，如果设置了此 uvm_reg_field 不支持按 field 访问。

* 检查此 uvm_reg_field 所在的寄存器是否设置了自己的 frontdoor，如果设置了，那么也是不能进行按 field 访问的，只能按照整个寄存器的方式访问。

* 得到最顶层的 uvm_reg_map，得到此 uvm_reg_map 的 adapter。检查 adapter 的 supports_byte_enable，这一标志位是与协议相关的。如果这一标志位为 1，那么就直接返回 1，表明是可以按照 field 来进行访问。

* 得到此 uvm_reg_field 所在的 uvm_reg 的所有的 uvm_reg_field。如果发现这个寄存器只有这一个 field 的话，那么就会把 sole_field 置位，并且最终会返回 0，表示不支持按照 field 访问。因为对于只有一个 field 的寄存器来说，访问一个 field 其实就是访问整个寄存器。
* 判断当前寄存器位是不是最高或者最低位，判断是否可以单独访问这个field，这里的判断标准其实就是把整个 64 按照 16 的总线位宽分成了 4 块区域，如果这个 field 占据了某个区域，那么要想能够按照 field 访问，其它的 field 就不能占据这个区域。


```systemverilog
function bit uvm_reg_field::is_indv_accessible(uvm_path_e  path,
                                               uvm_reg_map local_map);
   if (path == UVM_BACKDOOR) begin
      `uvm_warning("RegModel",
         {"Individual BACKDOOR field access not available for field '",
         get_full_name(), "'. Accessing complete register instead."})
      return 0;
   end

   if (!m_individually_accessible) begin
         `uvm_warning("RegModel",
            {"Individual field access not available for field '",
            get_full_name(), "'. Accessing complete register instead."})
      return 0;
   end

   // Cannot access individual fields if the container register
   // has a user-defined front-door
   if (m_parent.get_frontdoor(local_map) != null) begin
      `uvm_warning("RegModel",
                   {"Individual field access not available for field '",
                    get_name(), "' because register '", m_parent.get_full_name(), "' has a user-defined front-door. Accessing complete register instead."})
      return 0;
   end

   begin
     uvm_reg_map system_map = local_map.get_root_map();
     uvm_reg_adapter adapter = system_map.get_adapter();
     if (adapter.supports_byte_enable)
       return 1;
   end

   begin
     int fld_idx;
     int bus_width = local_map.get_n_bytes();
     uvm_reg_field fields[$];
     bit sole_field;

     //得到此 uvm_reg_field 所在的 uvm_reg 的所有的 uvm_reg_field
     m_parent.get_fields(fields);

     //如果这个寄存器只有这一个 field,不支持按照 field 访问
     if (fields.size() == 1) begin
        sole_field = 1;
     end
     else begin
        int prev_lsb,this_lsb,next_lsb; 
        int prev_sz,this_sz,next_sz; 
        int bus_sz = bus_width*8;

        foreach (fields[i]) begin
           if (fields[i] == this) begin
              fld_idx = i;
              break;
           end
        end

        this_lsb = fields[fld_idx].get_lsb_pos();
        this_sz  = fields[fld_idx].get_n_bits();

        //判断此 field 是不是最低位的 field，如果不是，说明还在更低位的
        if (fld_idx>0) begin
          prev_lsb = fields[fld_idx-1].get_lsb_pos();
          prev_sz  = fields[fld_idx-1].get_n_bits();
        end

        //判断此 field 是不是最高位的 field，如果不是，说明还在更高位的
        if (fld_idx < fields.size()-1) begin
          next_lsb = fields[fld_idx+1].get_lsb_pos();
          next_sz  = fields[fld_idx+1].get_n_bits();
        end

        // if first field in register
        if (fld_idx == 0 &&
           ((next_lsb % bus_sz) == 0 ||
            (next_lsb - this_sz) > (next_lsb % bus_sz)))
           return 1;

        // if last field in register
        else if (fld_idx == (fields.size()-1) &&
            ((this_lsb % bus_sz) == 0 ||
             (this_lsb - (prev_lsb + prev_sz)) >= (this_lsb % bus_sz)))
           return 1;

        // if somewhere in between
        else begin
           if ((this_lsb % bus_sz) == 0) begin
              if ((next_lsb % bus_sz) == 0 ||
                  (next_lsb - (this_lsb + this_sz)) >= (next_lsb % bus_sz))
                 return 1;
           end 
           else begin
              if ( (next_lsb - (this_lsb + this_sz)) >= (next_lsb % bus_sz) &&
                  ((this_lsb - (prev_lsb + prev_sz)) >= (this_lsb % bus_sz)) )
                 return 1;
           end
        end
     end
   end

   `uvm_warning("RegModel", 
       {"Target bus does not support byte enabling, and the field '",
       get_full_name(),"' is not the only field within the entire bus width. ",
       "Individual field access will not be available. ",
       "Accessing complete register instead."})

   return 0;

endfunction
```
