   XatomicX(1);

   m_write_in_progress = 1'b1;

   //例如一个寄存器是 64 位的，那么这里只会取 rw.value[0]中的最后 64 位
   rw.value[0] &= ((1 << m_n_bits)-1);
   value = rw.value[0];

   rw.status = UVM_IS_OK;

