            rw.element = f;
            rw.element_kind = UVM_FIELD;
            cb.pre_write(rw);
         end

         // 在 callback 中可能会更新 value 的值，所以这里需要重新读取 value 的值
         value = (value & ~msk) | (rw.value[0] << lsb);
      end
   end

   rw.element = this;
   rw.element_kind = UVM_REG;
   rw.value[0] = value;

