backdoor_read_func

* 被 [backdoor_read]() 调用

* 调用 [get_full_hdl_path]() 获取到绝对路径

* 遍历 paths 联合数组，遍历 hdl_concat 中的动态数组 slices 中的每一条记录。如果发现此条记录 的 offset 小于 0，那么调用 uvm_hdl_read 函数，得到寄存器的值，放入 val 中。否则的话也是调用 uvm_hdl_read 函数，只是把得到的值，放在 val 的特定的位中。

* 在调用 uvm_reg 的 configure 函数时，如果指定了 hdl 路径， 那么 configure 函数会调用 add_hdl_path_slice，传入的 offset 参数为-1。**offset 小于 0 也即意味着只有这一个 uvm_reg_field**。在 offset 不为 0 的情况下，那么也即意味着有多个 uvm_reg_field。此时 val 的不同位需要多次调用 uvm_hdl_read 函数来获取。

   ```
   hdl_concat.slices = '{
      '{path: "top.dut.reg_low",  offset: 0,  size: 16},
      '{path: "top.dut.reg_high", offset: 16, size: 16}
   };

   // Assume the actual values in HDL are:
   // top.dut.reg_low  = 16'hABCD
   // top.dut.reg_high = 16'h1234

   uvm_reg_data_t val;

   foreach (hdl_concat.slices[j]) begin
      `uvm_info("RegMem", $sformatf("backdoor_read from %s", hdl_concat.slices[j].path), UVM_DEBUG)

      if (hdl_concat.slices[j].offset < 0) begin
         // This condition is not met in our example
      end
      else begin
         uvm_reg_data_t slice;
         int k = hdl_concat.slices[j].offset;

         uvm_hdl_read(hdl_concat.slices[j].path, slice);

         // First iteration (j = 0):
         // slice = 16'hABCD, k = 0
         // Second iteration (j = 1):
         // slice = 16'h1234, k = 16

         repeat (hdl_concat.slices[j].size) begin
               val[k++] = slice[0];
               slice >>= 1;
         end
      end
   end

   // After the loop, val = 32'h1234ABCD
   ```

* [uvm_hdl_inca:uvm_hdl_read](https://github.com/jiru1997/VLSI-Design-verification-interview/blob/main/VLSI%20Design%20Verification/Functional%20Verification/UVM1.2%20source%20code%20analysis/09%3A%20uvm_dpi/chapter%2005%3A%20uvm_hdl_inca.md) 函数，这是一个用 C 语言写成的函数，其作用就是根据输入的字符串形式路径信息来获得这个这个路径所表示的寄存器的值。

```systemverilog
function uvm_status_e uvm_reg::backdoor_read_func(uvm_reg_item rw);
  uvm_hdl_path_concat paths[$];
  uvm_reg_data_t val;
  bit ok=1;

  //获取到当前 uvm_reg 的 backdoor 的绝对路径，存放到 paths 中
  get_full_hdl_path(paths,rw.bd_kind);

  //path 中存储的是 hdl_concat 类型的变量，一个 register 对应一条信息
  //每一个 hdl_concat 中存储当前 register 的每一个 field 的路径信息
  foreach (paths[i]) begin
     uvm_hdl_path_concat hdl_concat = paths[i];
     val = 0;

     //行遍历 hdl_concat 中的动态数组 slices 中的每一条记录
     //从后面读取数据，最终读取出来值的值存放到 val 中
     foreach (hdl_concat.slices[j]) begin
        `uvm_info("RegMem", {"backdoor_read from %s ",
               hdl_concat.slices[j].path},UVM_DEBUG)

        //如果发现此条记录的 offset 小于 0，那么调用 uvm_hdl_read 函数，得到寄存器的值，放入 val 中
        if (hdl_concat.slices[j].offset < 0) begin
           ok &= uvm_hdl_read(hdl_concat.slices[j].path,val);
           continue;
        end
        begin
           //调用 uvm_hdl_read 函数，把得到的值，放在 val 的特定的位中
           uvm_reg_data_t slice;
           int k = hdl_concat.slices[j].offset;

           ok &= uvm_hdl_read(hdl_concat.slices[j].path, slice);

           //根据 offset 的值把 val 的不同的位赋值为读取的值。
           repeat (hdl_concat.slices[j].size) begin
              val[k++] = slice[0];
              slice >>= 1;
           end
        end
     end

     //根据此寄存器的位宽，去除 val 中的无效位
     val &= (1 << m_n_bits)-1;

     //如果 i 为 0，表示此寄存器只有一个路径，因此得到的值是唯一的
     if (i == 0)
        rw.value[0] = val;

     //假如有两个路径，那么可能会得到两个值
     if (val != rw.value[0]) begin
        `uvm_error("RegModel", $sformatf("Backdoor read of register %s with multiple HDL copies: values are 
                not the same: %0h at path '%s', and %0h at path '%s'. Returning first value.",
               get_full_name(),
               rw.value[0], uvm_hdl_concat2string(paths[0]),
               val, uvm_hdl_concat2string(paths[i]))); 
        return UVM_NOT_OK;
      end
      `uvm_info("RegMem", 
         $sformatf("returned backdoor value 0x%0x",rw.value[0]),UVM_DEBUG);

  end

  //ok 的值是在调用 uvm_hdl_read 时候确定的
  rw.status = (ok) ? UVM_IS_OK : UVM_NOT_OK;
  return rw.status;
endfunction
