update

* 依次把添加到此 uvm_reg_block 的 uvm_reg 进行更新，把添加到此 uvm_reg_block 的 uvm_reg_block 进行更新

* 调用 [needs_update]() 来判断是否需要进行更新操作

* 调用 [uvm_reg:update]() 只有当m_mirrored和m_desired不相等时，update方法才写入该值

  <img width="600" alt="image" src="https://user-images.githubusercontent.com/66343787/182062657-65a22dbe-dcb3-4364-9b6b-d7cc3b88b1c9.png">

  <img width="600" alt="image" src="https://user-images.githubusercontent.com/66343787/182062688-29b70af5-9396-4d15-84f1-e4364572b9d9.png">


```systemverilog
task uvm_reg_block::update(output uvm_status_e  status,
                           input  uvm_path_e    path = UVM_DEFAULT_PATH,
                           input  uvm_sequence_base  parent = null,
                           input  int                prior = -1,
                           input  uvm_object         extension = null,
                           input  string             fname = "",
                           input  int                lineno = 0);
   status = UVM_IS_OK;

   if (!needs_update()) begin
     `uvm_info("RegModel", $sformatf("%s:%0d - RegModel block %s does not need updating",
                    fname, lineno, this.get_name()), UVM_HIGH);
      return;
   end

   `uvm_info("RegModel", $sformatf("%s:%0d - Updating model block %s with %s path",
                    fname, lineno, this.get_name(), path.name ), UVM_HIGH);

   foreach (regs[rg_]) begin
      uvm_reg rg = rg_;
      if (rg.needs_update()) begin
         rg.update(status, path, null, parent, prior, extension);
         if (status != UVM_IS_OK && status != UVM_HAS_X) begin;
           `uvm_error("RegModel", $sformatf("Register \"%s\" could not be updated",
                                        rg.get_full_name()));
           return;
         end
      end
   end

   foreach (blks[blk_]) begin
     uvm_reg_block blk = blk_;
     blk.update(status,path,parent,prior,extension,fname,lineno);
   end
endtask: update
