```systemverilog
function void uvm_reg_block::add_hdl_path(string path, string kind = "RTL");

  // Declare a queue to store HDL paths
  uvm_queue #(string) paths;

  // Get the queue of paths for the specified HDL kind from the pool
  paths = hdl_paths_pool.get(kind);

  // Add the new path to the queue
  paths.push_back(path);

endfunction
```


---

get_full_hdl_path

* 被 [uvm_reg:get_full_hdl_path](https://github.com/jiru1997/VLSI-Design-verification-interview/blob/main/VLSI%20Design%20Verification/Functional%20Verification/UVM1.2%20source%20code%20analysis/11%3A%20uvm_reg/chapter%2003%3A%20uvm_reg.md) 调用，返回后面访问的父路径，通过和子路径拼接后得到一个完整路径
* 函数功能：
   * 假设调用过 [set_hdl_path_root]() 函数设置过绝对路径，那么无论这个 uvm_reg_block 是不是最顶层的 uvm_reg_block，都会直接返回这个路径。否则的话，这个函数会返回父路径加上本地路径，也即此 uvm_reg_block 的绝对路径。无论哪种情况，get_full_hdl_path 最终都是返回了此 uvm_reg_block 的绝对路径。

```systemverilog
//通过uvm_reg_block::add_hdl_path函数将寄存器模型关联到DUT一端
add_hdl_path("reg_backdoor_access.dut");

//通过uvm_reg::add_hdl_path_slice函数将寄存器模型中的各个寄存器成员与HDL一侧的地址进行映射
chnl0_ctrl_reg.add_hdl_path_slice($sformatf("regs[%0d]", `SLVO_RW_REG), 0, 32);
```

* 默认传入的 kind 是 RTL，清空 paths 数组，以防止其中的内容在最后返回后被误认为是由 get_full_hdl_path 添加进去的。

* 调用 [is_hdl_path_root]() 查看 root_hdl_paths 中是否有对应 kind 的记录。因此，假如这是一个最顶层的 uvm_reg_block，那么 get_full_hdl_path 会把此绝对路径放入 paths 数组中，并直接返回。即使不是最顶层的 uvm_reg_block，那么假如调用了 [set_hdl_path_root]() 函数，也是会把此路径放入 paths 中，直接返回的。

* 从 [hdl_paths_pool]() 中得到索引为 kind 的路径所在的队列。递归调用父 uvm_reg_block 的 get_full_hdl_path 函数，得到父路径。

* 在父 uvm_reg_block 没有设置过路径或者这本身就是一个最顶层的 uvm_reg_block 时，把本地路径放入 paths 联合数组中。
* 当父 uvm_reg_block 的 get_full_hdl_path 返回了路径时，将父路径和子路径连接成为一个绝对路径。

```systemverilog
function void uvm_reg_block::get_full_hdl_path(ref string paths[$],
                                               input string kind = "",
                                               string separator = ".");

   if (kind == "")
      kind = get_default_hdl_path();

   //清空 paths 数组，以防止其中的内容在最后返回后被误认为是由 get_full_hdl_path 添加进去的
   paths.delete();

   //在最顶层的 uvm_reg_block,把最顶层的 uvm_reg_block 的路径写入此 uvm_reg_block的 root_hdl_paths 中
   if (is_hdl_path_root(kind)) begin
      if (root_hdl_paths[kind] != "")
         paths.push_back(root_hdl_paths[kind]);
      //把此绝对路径放入 paths 数组中，并直接返回
      return;
   end

   //检查此 uvm_reg_block 的 hdl_paths_pool 中是否定义了索引为 kind，即”RTL”的路径
   //(检查是否给这个 uvm_reg_block 设置过路径)
   if (!has_hdl_path(kind)) begin
      `uvm_error("RegModel",{"Block does not have hdl path defined for abstraction '",kind,"'"})
      return;
   end

   begin
      uvm_queue #(string) hdl_paths = hdl_paths_pool.get(kind);
      string parent_paths[$];

      //递归的调用父 uvm_reg_block 的 get_full_hdl_path 函数，得到父路径。
      if (parent != null)
         parent.get_full_hdl_path(parent_paths, kind, separator);

      for (int i=0; i<hdl_paths.size();i++) begin
         string hdl_path = hdl_paths.get(i);

         if (parent_paths.size() == 0) begin
            if (hdl_path != "")
               paths.push_back(hdl_path);

            continue;
         end

         //把这些路径加上本地路径后放入 paths 联合数组中。
         //假设父路径为 top_tb.dut_inst，本地路径为 mac_inst，
         //那么最终放入 paths 中的路径为 top_tb.dut_inst.mac_inst。
         foreach (parent_paths[j])  begin
            if (hdl_path == "")
               paths.push_back(parent_paths[j]);
            else
               paths.push_back({ parent_paths[j], separator, hdl_path });
         end
      end
   end

endfunction
```

