   typedef enum {UNKNOWNS, ZEROES, ONES, ADDRESS, VALUE, INCR, DECR} init_e;

   local bit               m_locked;            // Indicates if the memory model is locked
   local bit               m_read_in_progress;  // Indicates if a read operation is in progress
   local bit               m_write_in_progress; // Indicates if a write operation is in progress
