   // info that is valid only if top-level map
   local uvm_reg_addr_t     m_base_addr;        // Base address of the map
   local int unsigned       m_n_bytes;          // Number of bytes in each register access
   local uvm_endianness_e   m_endian;           // Endianness of the map (UVM_LITTLE_ENDIAN or UVM_BIG_ENDIAN)
