add_submap

* 将一个 uvm_reg_block 添加到另外一个 uvm_reg_block 的时候会调用这个函数

  ```systemverilog
  function void build();
    default_map = create_map("default_map", 0, 2, UVM_LITTLE_ENDIAN, 0);
    // 寄存器是 uvm_object 类型，所以不给 parent(第三个参数用作路径匹配，完整路径: my_reg_blk.gb_ins)
    gb_ins = global_blk::type_id::create("gb_ins", , get_full_name());
    gb_ins.configure(this, "global_reg");
    // build 方法需要自定义，并不是由系统提供，通常在 build 函数中实力化所有包含的内存相关组件并调用 configure 方法 和 build 方法
    gb_ins.build();
    gb_ins.lock_model();
    default_map.add_submap(gb_ins.default_map, 16'h0); 
  endfunction
  ```

* 保证 child_map 没有加入到其它的 uvm_reg_map 中。
* 一方面保证要加入的 child_map 已经从属于某个 uvm_reg_block 了，另外一方面保证要加入的 child_map 所从属的 uvm_reg_block 和此 map 在同一个 uvm_reg_block 中。
* 检查要加入的 child_map 和此 map 的位宽是否一致。如果此 map 的位宽大于 child_map 的位宽，那么给出警告信息。

* 调用[add_parent_map]() 和 [set_submap_offset]() 来给 m_submaps 插入一条相同的信息

```systemverilog
function void uvm_reg_map::add_submap (uvm_reg_map child_map,
                                       uvm_reg_addr_t offset);
   uvm_reg_map parent_map;

   // Check if child_map is null
   if (child_map == null) begin
      `uvm_error("RegModel", {"Attempting to add NULL map to map '",get_full_name(),"'"})
      return;
   end

   parent_map = child_map.get_parent_map();

   // Ensure child_map doesn't already have a parent
   if (parent_map != null) begin
      `uvm_error("RegModel", {"Map '", child_map.get_full_name(),
                 "' is already a child of map '",
                 parent_map.get_full_name(),
                 "'. Cannot also be a child of map '",
                 get_full_name(),
                 "'"})
      return;
   end

   begin : parent_block_check
     uvm_reg_block child_blk = child_map.get_parent();
     // Ensure child_map has a parent block
     if (child_blk == null) begin
        `uvm_error("RegModel", {"Cannot add submap '",child_map.get_full_name(),
                   "' because it does not have a parent block"})
        return;
     end
     // Check if child_map's parent block is a descendant of this map's parent block
     while((child_blk!=null) && (child_blk.get_parent() != get_parent()))
	     	child_blk = child_blk.get_parent();

     if (child_blk==null) begin
        `uvm_error("RegModel",
          {"Submap '",child_map.get_full_name(),"' may not be added to this ",
          "address map, '", get_full_name(),"', as the submap's parent block, '",
          child_blk.get_full_name(),"', is neither this map's parent block nor a 
          descendent of this map's parent block, '",
          m_parent.get_full_name(),"'"})
      return;
     end
   end

   begin : n_bytes_match_check
      // Warn if child_map has fewer bytes than parent map
      if (m_n_bytes > child_map.get_n_bytes(UVM_NO_HIER)) begin
         `uvm_warning("RegModel",
             $sformatf("Adding %0d-byte submap '%s' to %0d-byte parent map '%s'",
                       child_map.get_n_bytes(UVM_NO_HIER), child_map.get_full_name(),
                       m_n_bytes, get_full_name()));
      end
   end

   // Add this map as parent to child_map
   child_map.add_parent_map(this,offset);
   // Set offset of child_map in this map
   set_submap_offset(child_map, offset);

endfunction: add_submap
```
