do_reg_item

* 这里只能处理寄存器类型的 transaction
```systemverilog
  virtual task do_reg_item(uvm_reg_item rw);
    // Convert register item to string for logging
    string rws = rw.convert2string();

    // Check if sequencer is properly set
    if (m_sequencer == null)
      `uvm_fatal("REG/DO_ITEM/NULL","do_reg_item: m_sequencer is null") 

    // Check if adapter is properly set
    if (adapter == null)
      `uvm_fatal("REG/DO_ITEM/NULL","do_reg_item: adapter handle is null") 

    // Log the transaction being processed
    `uvm_info("DO_RW_ACCESS",{"Doing transaction: ",rws},UVM_HIGH)

    // Handle parent selection for hierarchical sequences
    if (parent_select == LOCAL) begin
      upstream_parent = rw.parent;
      rw.parent = this;
    end

    // Perform bus write or read based on the kind of register access
    if (rw.kind == UVM_WRITE)
      rw.local_map.do_bus_write(rw, m_sequencer, adapter);
    else
      rw.local_map.do_bus_read(rw, m_sequencer, adapter);

    // Restore original parent if LOCAL parent selection was used
    if (parent_select == LOCAL)
       rw.parent = upstream_parent;
  endtask
