uvm_tlm_generic_payload

* General purpose transaction class for memory-mapped bus-based systems

```systemverilog
class uvm_tlm_generic_payload extends uvm_sequence_item;

   // Variable: m_address
   // Address for the bus operation
   // This 64-bit field specifies the starting address for the transaction.
   // It is used to indicate where in memory the operation should occur.
   rand bit [63:0] m_address;

   // Variable: m_command
   // Bus operation type
   // This enumerated type specifies whether the transaction is a read, write, or ignore command.
   // It determines the direction of data transfer or if the transaction should be ignored.
   rand uvm_tlm_command_e m_command;

   // Variable: m_data
   // Data read or to be written
   // This dynamic array holds the actual data being transferred.
   // For write operations, it contains the data to be written; for read operations, it will store the data read.
   rand byte unsigned m_data[];

   // Variable: m_length
   // Number of bytes to be copied to/from m_data array
   // This field specifies the size of the data transfer in bytes.
   // It indicates how many bytes should be read from or written to the m_data array.
   rand int unsigned m_length;

   // Variable: m_response_status
   // Status of the bus operation
   // This enumerated type provides information about the outcome of the transaction,
   // such as whether it completed successfully or encountered an error.
   rand uvm_tlm_response_status_e m_response_status;

   // Variable: m_dmi
   // DMI (Direct Memory Interface) mode indicator
   // This bit, when set, indicates that the transaction should use DMI if available.
   // Note: DMI is not yet supported in the UVM TLM2 subset.
   bit m_dmi;

   // Variable: m_byte_enable
   // Indicates valid m_data array elements
   // This array is used for fine-grained control over which bytes in the m_data array are valid or should be accessed.
   // Each byte in m_byte_enable corresponds to a byte in m_data.
   rand byte unsigned m_byte_enable[];

   // Variable: m_byte_enable_length
   // Number of elements in m_byte_enable array
   // This field specifies the length of the m_byte_enable array.
   // It is used to determine how many bytes are controlled by the byte enable feature.
   rand int unsigned m_byte_enable_length;

   // Variable: m_streaming_width
   // Number of bytes transferred on each beat
   // This field is used in burst transfers to specify how many bytes are transferred in each beat of the burst.
   // A value of 0 indicates that the streaming width is identical to the length of the entire transfer.
   rand int unsigned m_streaming_width;

   // Variable: m_extensions
   // Associative array to store transaction extensions
   // This allows additional, user-defined attributes to be added to the generic payload.
   // The key is of type uvm_tlm_extension_base, allowing for type-safe extensions.
   protected uvm_tlm_extension_base m_extensions [uvm_tlm_extension_base];

   // Variable: m_rand_exts
   // Array of randomizable extensions
   // This array holds references to extensions that should be included in randomization of the generic payload.
   local rand uvm_tlm_extension_base m_rand_exts[];
