  			item req,rsp;
  			temp = create_item(item::get_type(),m_sequencer,"req");

  			void'($cast(req,temp));
  			start_item(req);

  			//在 start_item 和 finish_item 之间需要对 sequence item 进行 randomize
  			req.randomize with{data==20;};
  			finish_item(req);
  			get_response(temp);

