  			`uvm_info("sequence","sequence already recive item", UVM_LOW)
  			`uvm_info("data_auto",$sformatf("%d",rsp.data_auto), UVM_LOW)
  			`uvm_info("data_noauto",$sformatf("%d",rsp.data_noauto), UVM_LOW)
