11.sequence之间的同步

* sequence之间的简单同步

  * 通过 event 可以同步两个 sequence

    ```systemverilog
    event send_over;//global event
    class drv0_seq extends uvm_sequence #(my_transaction);
       my_transaction m_trans;
       `uvm_object_utils(drv0_seq)

       virtual task body();
          if(starting_phase != null) 
             starting_phase.raise_objection(this);
          `uvm_do_with(m_trans, {m_trans.pload.size == 1500;})
          ->send_over;
       endtask
    endclass

    class drv1_seq extends uvm_sequence #(my_transaction);
       my_transaction m_trans;
       `uvm_object_utils(drv1_seq)

       virtual task body();
          if(starting_phase != null) 
             starting_phase.raise_objection(this);
          @send_over;
       endtask
    endclass
    ```

* sequence之间的复杂同步

  * 通过 virtual sequence 可以同步两个 sequence

    ```systemverilog
    class case0_vseq extends uvm_sequence;
       `uvm_object_utils(case0_vseq)
       `uvm_declare_p_sequencer(my_vsqr) 
       function new(string name = "case0_vseq");
          super.new(name);
       endfunction

       virtual task body();
          my_transaction tr;
          drv0_seq seq0;
          drv1_seq seq1;
          if(starting_phase != null) 
             starting_phase.raise_objection(this);
          `uvm_do_on_with(tr, p_sequencer.p_sqr0, {tr.pload.size == 1500;})
          `uvm_info("vseq", "send one longest packet on p_sequencer.p_sqr0", UVM_MEDIUM)
          fork
             `uvm_do_on(seq0, p_sequencer.p_sqr0);
             `uvm_do_on(seq1, p_sequencer.p_sqr1);
          join 
          #100;
          if(starting_phase != null) 
             starting_phase.drop_objection(this);
       endtask
    endclass
    ```

