    phase.raise_objection(this);

    // Write to memory
    trans = new("trans");
    trans.set_command(UVM_TLM_WRITE_COMMAND);
    trans.set_address(100);
    data = new[4];
    data = {8'hDE, 8'hAD, 8'hBE, 8'hEF};
    trans.set_data(data);
    trans.set_data_length(4);

    initiator_socket.b_transport(trans, delay);

    `uvm_info("TEST", $sformatf("Write completed, delay: %0d ns", delay.get_realtime()), UVM_LOW)

    // Read from memory
    trans = new("trans");
    trans.set_command(UVM_TLM_READ_COMMAND);
    trans.set_address(100);
    data = new[4];
    trans.set_data(data);
    trans.set_data_length(4);

    initiator_socket.b_transport(trans, delay);

    trans.get_data(data);
    `uvm_info("TEST", $sformatf("Read completed, data: %h %h %h %h, delay: %0d ns", 
              data[0], data[1], data[2], data[3], delay.get_realtime()), UVM_LOW)

    phase.drop_objection(this);
  endtask
endclass
