3. 静态类

* static也可以声明class, 表示静态类。静态类和静态变量类似，只不过静态类可以封装更多内容。声明静态类的class, 该class的所有实例都可以共享这一个静态类.
* `uvm_object`内建了很多方法, `compare(), print()`等，依靠`comparer, printer`实现，其内部定义了各种policy和函数，依照 `field_automation` 机制，调用宏中封装的 `_m_uvm_field_automatic()` 函数。
* 每个继承于uvm_object的类都可以通过`comparer, printer`进行`compare, print`操作, 所以uvm便创建了一个静态类的容器, 方便管理。
* 静态类 `__m_uvm_status_container` 的例化: `static /*protected*/ uvm_status_container _m_uvm_status_container = new`;
* 这个类包含了`compare, printer`等，一般默认使用`uvm_object_globals.svh`中的全局变量，`uvm_default_comparer, uvm_default_table_printer`。也可以自己配置`compare, printer`中的参数，并在调用`compare(), print()`时传入即可或者重写`do_compare, do_print`函数，实现自定义功能。

    ```systemverilog
    # uvm_object_globals.svh

    // Variable: uvm_default_comparer
    //
    //
    // The default compare policy. Used when calls to <uvm_object::compare>
    // do not specify a comparer policy.

    uvm_comparer uvm_default_comparer = new(); // uvm_comparer::init();

    # uvm_misc.svh

    //------------------------------------------------------------------------------
    //
    // CLASS- uvm_status_container
    //
    // Internal class to contain status information for automation methods.
    //
    //------------------------------------------------------------------------------

    class uvm_status_container;

      //These are the policy objects currently in use. The policy object gets set
      //when a function starts up. The macros use this.
      uvm_comparer    comparer;
      uvm_packer      packer;
      uvm_recorder    recorder;
      uvm_printer     printer;

    # uvm_object_defines.svh
    `define uvm_field_int(ARG,FLAG) \
      begin \
        case (what__) \
         .........
          UVM_COMPARE: \
            begin \
              if(local_data__ == null) return; \
              if(!((FLAG)&UVM_NOCOMPARE)) begin \
                if(ARG !== local_data__.ARG) begin \
                   void'(__m_uvm_status_container.comparer.compare_field(`"ARG`", ARG, local_data__.ARG, $bits(ARG))); \
                   if(__m_uvm_status_container.comparer.result && (__m_uvm_status_container.comparer.show_max <= __m_uvm_status_container.comparer.result)) return; \
                end \
              end \
            end \
          ........
          UVM_PRINT: \
            if(!((FLAG)&UVM_NOPRINT)) begin \
              __m_uvm_status_container.printer.print_int(`"ARG`", ARG, $bits(ARG), uvm_radix_enum'((FLAG)&UVM_RADIX)); \
            end \
          ........
        endcase \
      end

    # uvm_object.svh

    virtual class uvm_object extends uvm_void;

        static /*protected*/ uvm_status_container __m_uvm_status_container = new;

    // compare
    // -------

    function bit  uvm_object::compare (uvm_object rhs,
                                       uvm_comparer comparer=null);
      bit t, dc;
      static int style;
      bit done;
      done = 0;
      if(comparer != null) 
        __m_uvm_status_container.comparer = comparer;
      else 
        __m_uvm_status_container.comparer = uvm_default_comparer;
      comparer = __m_uvm_status_container.comparer;

      if(!__m_uvm_status_container.scope.depth()) begin
        comparer.compare_map.clear();
        comparer.result = 0;
        comparer.miscompares = "";
        comparer.scope = __m_uvm_status_container.scope;
        if(get_name() == "")
          __m_uvm_status_container.scope.down("<object>");
        else
          __m_uvm_status_container.scope.down(this.get_name());
      end
      if(!done && (rhs == null)) begin
        if(__m_uvm_status_container.scope.depth()) begin
          comparer.print_msg_object(this, rhs);
        end
        else begin
          comparer.print_msg_object(this, rhs);
          uvm_report_info("MISCMP",
               $sformatf("%0d Miscompare(s) for object %s@%0d vs. null", 
               comparer.result, 
               __m_uvm_status_container.scope.get(),
                this.get_inst_id()),
                __m_uvm_status_container.comparer.verbosity);
          done = 1;
        end
      end
      if(!done && (comparer.compare_map.get(rhs) != null)) begin
        if(comparer.compare_map.get(rhs) != this) begin
          comparer.print_msg_object(this, comparer.compare_map.get(rhs));
        end 
        done = 1;  //don't do any more work after this case, but do cleanup
      end
      if(!done && comparer.check_type && (rhs != null) && (get_type_name() != rhs.get_type_name())) begin
        __m_uvm_status_container.stringv = { "lhs type = \"", get_type_name(), 
                         "\" : rhs type = \"", rhs.get_type_name(), "\""};
        comparer.print_msg(__m_uvm_status_container.stringv);
      end
      if(!done) begin
        comparer.compare_map.set(rhs, this);
        __m_uvm_field_automation(rhs, UVM_COMPARE, "");
        dc = do_compare(rhs, comparer);
      end
      if(__m_uvm_status_container.scope.depth()==1)  begin
        __m_uvm_status_container.scope.up();
      end

      if(rhs != null)
        comparer.print_rollup(this, rhs);
      return (comparer.result == 0 && dc == 1);
    endfunction


    // do_compare
    // ----------

    function bit  uvm_object::do_compare (uvm_object rhs,
                                          uvm_comparer comparer);
      return 1;
    endfunction

    ```

