ACCESS方式 —— reg write

* 创建`uvm_reg_item`实例 `rw`，一般不用指定其 `uvm_sequence_base`型的`parent`。但是**FRONTDOOR**形式发送`transaction`需要通过`sequence`来协助完成，会自动创建一个`sequence`。
* 可以指定`map`，通过选定的`map`访问寄存器。举例：CPU的 IBUS 和 SBUS访问的地址范围不同，可以分别建立相对应的`uvm_reg_map`，通过`map`的`set_sequencer`设置对应BUS的`sequencer`。
* 调用`uvm_reg`的`do_write(rw)`。

  ```
  // uvm_reg.svh
  task uvm_reg::write(output uvm_status_e      status,
                      input  uvm_reg_data_t    value,
                      input  uvm_path_e        path = UVM_DEFAULT_PATH,
                      input  uvm_reg_map       map = null,
                      input  uvm_sequence_base parent = null,
                      input  int               prior = -1,
                      input  uvm_object        extension = null,
                      input  string            fname = "",
                      input  int               lineno = 0);

     // create an abstract transaction for this operation
     uvm_reg_item rw;
     XatomicX(1);
     set(value);
     rw = uvm_reg_item::type_id::create("write_item",,get_full_name());
     rw.element      = this;
     rw.element_kind = UVM_REG;
     rw.kind         = UVM_WRITE;
     rw.value[0]     = value;
     rw.path         = path;
     rw.map          = map;
     rw.parent       = parent;
     rw.prior        = prior;
     rw.extension    = extension;
     rw.fname        = fname;
     rw.lineno       = lineno;
     do_write(rw);
     status = rw.status;
     XatomicX(0);
  endtask
  ```

* `local_map`是`uvm_reg`，`uvm_reg_filed`，`uvm_mem`所在`uvm_reg_map`的指针。
* `get_root_map`获得最顶层的`map`，如果是套嵌的`uvm_reg_block`，`uvm_reg_map`也是套嵌的。
* 可以用户自己定义**FORONTDOOR**，一般使用内建的方式，调用`rw.local_map.do_write(rw)`。
* **一般设置`default_map.set_auto_predict(1)`，这样当寄存器访问结束时，会调用`do_predict`，自动更新`uvm_reg_filed`中的三个变量值。**

  ```
  // uvm_reg.svh
  // do_write
  task uvm_reg::do_write (uvm_reg_item rw);
  ....
  // EXECUTE WRITE...
  case (rw.path)

     // ...VIA USER BACKDOOR
     UVM_BACKDOOR: begin
     ....
     end
     UVM_FRONTDOOR: begin

        uvm_reg_map system_map = rw.local_map.get_root_map();
        m_is_busy = 1;
        // ...VIA USER FRONTDOOR
        ....
        // ...VIA BUILT-IN FRONTDOOR
        else begin : built_in_frontdoor
           rw.local_map.do_write(rw);
        end
        m_is_busy = 0;
        if (system_map.get_auto_predict()) begin
           uvm_status_e status;
           if (rw.status != UVM_NOT_OK) begin
              sample(value, -1, 0, rw.map);
              m_parent.XsampleX(map_info.offset, 0, rw.map);
           end
           status = rw.status; // do_predict will override rw.status, so we save it here
           do_predict(rw, UVM_PREDICT_WRITE);
           rw.status = status;
        end
     end
  endcase
  ```

* 自动创建一个`sequence`，作为`rw`的`parent`。
* 使用寄存器模型一般采用加入`adapter`的方式，所以走`do_bus_write(rw，sequencer，adapter)`的分支。

  ```
  // uvm_reg_map.svh
  // do_write(uvm_reg_item rw)

  task uvm_reg_map::do_write(uvm_reg_item rw);

    uvm_sequence_base tmp_parent_seq;
    uvm_reg_map system_map = get_root_map();
    uvm_reg_adapter adapter = system_map.get_adapter();
    uvm_sequencer_base sequencer = system_map.get_sequencer();

    .....

    if (rw.parent == null) begin
       rw.parent = new("default_parent_seq");
       tmp_parent_seq = rw.parent;
    end
    if (adapter == null) begin
      .....
    end
    else begin
      do_bus_write(rw, sequencer, adapter);
    end
    if (tmp_parent_seq != null)
      sequencer.m_sequence_exiting(tmp_parent_seq);
  endtask

  // get_root_map
  function uvm_reg_map uvm_reg_map::get_root_map();
     return (m_parent_map == null) ? this : m_parent_map.get_root_map();
  endfunction: get_root_map

  // get_sequencer
  function uvm_sequencer_base uvm_reg_map::get_sequencer(uvm_hier_e hier=UVM_HIER);
    if (hier == UVM_NO_HIER || m_parent_map == null)
      return m_sequencer;
    return m_parent_map.get_sequencer(hier);
  endfunction

  // get_adapter
  function uvm_reg_adapter uvm_reg_map::get_adapter(uvm_hier_e hier=UVM_HIER);
    if (hier == UVM_NO_HIER || m_parent_map == null)
      return m_adapter;
    return m_parent_map.get_adapter(hier);
  endfunction
  ```

* `uvm_reg_map`中的`do_bus_write`将`rw`转化成`uvm_reg_bus_op`类型的`rw_access`。然后在调用`adapter.reg2bus(rw_access)`转化得到`bus sequencer`可以接受的`transaction`类型。
* `rw.parent.finish_item(bus_req)` `rw.parent.finish_item(bus_req)`相当于平常调用`sequence`中的`body()`函数，完成与`driver`的握手。
* 可以手动设置`response`，也可以使用`driver`自动返回的`response`，根据`status`判断写状态。

  ```
  // uvm_reg_map.svh
  // do_bus_write

  task uvm_reg_map::do_bus_write (uvm_reg_item rw,
                                  uvm_sequencer_base sequencer,
                                  uvm_reg_adapter adapter);

    uvm_reg_addr_t     addrs[$];
    uvm_reg_map        system_map = get_root_map();
    int unsigned       bus_width  = get_n_bytes();
    uvm_reg_byte_en_t  byte_en    = -1;
    uvm_reg_map_info   map_info;
    int                n_bits;
    int                lsb;
    int                skip;
    int unsigned       curr_byte;
    int                n_access_extra, n_access;
    int               n_bits_init;

    Xget_bus_infoX(rw, map_info, n_bits_init, lsb, skip);
    addrs=map_info.addr;

    .........

      foreach(addrs[i]) begin: foreach_addr
        uvm_sequence_item bus_req;
        uvm_reg_bus_op rw_access;
        uvm_reg_data_t data;

        data = (value >> (curr_byte*8)) & ((1'b1 << (bus_width * 8))-1);

        `uvm_info(get_type_name(),
           $sformatf("Writing 'h%0h at 'h%0h via map \"%s\"...",
                data, addrs[i], rw.map.get_full_name()), UVM_FULL);

        if (rw.element_kind == UVM_FIELD) begin
          for (int z=0;z<bus_width;z++)
            rw_access.byte_en[z] = byte_en[curr_byte+z];
        end
        rw_access.kind    = rw.kind;
        rw_access.addr    = addrs[i];
        rw_access.data    = data;
        rw_access.n_bits  = (n_bits > bus_width*8) ? bus_width*8 : n_bits;
        rw_access.byte_en = byte_en;

