uvm_hdl_read

* 使用uvm_hdl_read常见的写法可能是这样：

  ```systemverilog
  bit rd_data_hdl;
  if(uvm_hdl_read("tb.xxx",rd_data_hdl)) begin
  ....
  end
  if(rd_data_hdl == 1) ....
  ```

* 上述的代码存在两个问题：
  * 使用了bit而非logic类型数据: bit类型是两态信号，其取值可能是0或1，而logic是4态信号。所以使用bit类型数据，无法识别出RTL中X或者Z态数据。
  * 使用'=='判断相等，而不是'===': '=='无法判断出x态或z态。而'==='则会严格检查相等

    ```systemverilog
    import uvm_pkg::*;
    `include "uvm_macros.svh"

    class test extends uvm_test;
      `uvm_component_utils(test)
      function new(string name="test",uvm_component parent = null);
          super.new(name,parent);
      endfunction

      virtual task main_phase(uvm_phase phase);
          super.main_phase(phase);
          phase.raise_objection(this);
          hdl_read_x();
          #7;
          hdl_read_x();
          phase.drop_objection(this);
      endtask
      virtual function void hdl_read_x();
          logic hdl_rd_logic;
          bit   hdl_rd_bit;
          void'(uvm_hdl_read("tb_top.clk",hdl_rd_bit));
          void'(uvm_hdl_read("tb_top.clk_x",hdl_rd_logic));
          $display("");
          $display("hdl_rd_bit=%0x",hdl_rd_bit);
          $display("hdl_rd_logic=%0x",hdl_rd_logic);

          $display("hdl_rd_bit==0 result: %0d",hdl_rd_bit==0);
          $display("hdl_rd_bit==1 result: %0d",hdl_rd_bit==1);
          $display("hdl_rd_bit==x result: %0d",hdl_rd_bit==1'hx);
          $display("hdl_rd_bit==z result: %0d",hdl_rd_bit==1'hz);
          $display("hdl_rd_bit===0 result: %0d",hdl_rd_bit===0);
          $display("hdl_rd_bit===1 result: %0d",hdl_rd_bit===1);
          $display("hdl_rd_bit===x result: %0d",hdl_rd_bit===1'hx);
          $display("hdl_rd_bit===z result: %0d\n",hdl_rd_bit===1'hz);

          $display("hdl_rd_logic==0 result: %0d",hdl_rd_logic==0);
          $display("hdl_rd_logic==1 result: %0d",hdl_rd_logic==1);
          $display("hdl_rd_logic==x result: %0d",hdl_rd_logic==1'hx);
          $display("hdl_rd_logic==z result: %0d",hdl_rd_logic==1'hz);
          $display("hdl_rd_logic===0 result: %0d",hdl_rd_logic===0);
          $display("hdl_rd_logic===1 result: %0d",hdl_rd_logic===1);
          $display("hdl_rd_logic===x result: %0d",hdl_rd_logic===1'hx);
          $display("hdl_rd_logic===z result: %0d",hdl_rd_logic===1'hz);
      endfunction
    endclass
    program tb_top;
      logic clk, clk_x;
     initial begin
          run_test("test");
     end
      initial  begin
          clk = 0;
          forever #5 clk = ~clk;
      end
      initial  begin
          clk_x = 0;
          #2;
          clk_x = 'hx;
      end
    endprogram
    ```

捕获后门路径信号的跳变

* 借助systemverilog种阻塞等待操作，可以精确地捕获信号的跳变，比如@和wait：

  ```systemverilog
  //信号Hierarchy读取
  @(tb_top.dut.cnt) 
  @(posedge dut.clk)

  //interface连接
  @(negedge vrf.clk)
  @(posedge vrf.axi_bid)
  wait(vrf.cnt==3)
  ```

* VPI接口是一次性的函数的调用来获取信号值，但无法把一个变量和DUT信号"绑定"，因此下述的代码是无法实现此目的。
* 如果需要获取信号的跳变，则需要使用封装task实现。以检测上升沿为例，该task的思路如下：

  ```systemverilog
  task at_posedge(string x_path);
      int t_value,delta;
      if(!uvm_hdl_check_path(x_path)) begin
          //report error
          return;
      end
      while(1) begin
          #delta;
          void'(uvm_hdl_read(x_path,t_value));
          if(t_value==0) break;
      end
      while(1) begin
          #delta;
          void'(uvm_hdl_read(x_path,t_value));
          if(t_value==1) break;
      end
  endtask
  ```
